  ["Twilight mist kisses the hair, lazy and lingering."] = "A névoa crepuscular beija os cabelos, preguiçosa e persistente.",
  ["Snowland Explorer"] = "Explorador da neve",
  ["One-Click Support"] = "Suporte com um clique",
  ["You can tell by the luster of these ribs that the pork I sell is very fresh."] = "Dá para perceber pelo brilho dessas costelas que a carne de porco que vendo é muito fresca.",
  ["\"Etymological Study of Ancient Feysac\""] = "\"Estudo Etimológico do Antigo Feysac\"",
