  ["<Assistant_Title1>Favor of the Disciple of Silence</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the <Silence Disciple> trait"] = "<Assistant_Title1> Favor do Discípulo do Silêncio </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <Silence Disciple>",
  ["Desire never lies; the gamble draws you in. See through the truth of the bullet and become the winner of desire."] = "O desejo nunca mente; a aposta atrai você. Veja a verdade da bala e torne-se o vencedor do desejo.",
  ["Sincere as the new moon blooming, the silent vow is hotter than fresh blood."] = "Sincero como a lua nova florescendo, o voto silencioso é mais quente que sangue fresco.",
