  ["Somewhat Dangerous"] = "Um pouco perigoso",
  ["<Assistant_Title1>【Organization Attribute Description】</>\nOrganization-related attributes mainly include <Assistant_Property1>Charm</>, <Assistant_Property1>Intuition</>, <Assistant_Property1>Knowledge</>, <Assistant_Property1>Might</>. TRPG Talents can provide additional permanent attribute bonuses, and some areas can provide temporary attribute bonuses.\n\n<Assistant_Title3>Recommended Searches: </>{SendAnswer:[Covenant Selection and Attribute Point Allocation]|1274}"] = "<Assistant_Title1> 【Descrição do atributo da organização】 </> \nOs atributos relacionados à organização incluem principalmente <Assistant_Property1> Charme </>, <Assistant_Property1> Intuição </>, <Assistant_Property1> Conhecimento </>, <Assistant_Property1> Pode </>. Talentos TRPG podem fornecer bônus de atributos permanentes adicionais, e algumas áreas podem fornecer bônus de atributos temporários.\n\n <Assistant_Title3> Pesquisas recomendadas: </> {SendAnswer:[Covenant Selection and Attribute Point Allocation]|1274}",
  ["<Assistant_Title1>【How to Join a Covenant】</>\nOnce the Covenant is unlocked, you can enter the joining process through the <Assistant_System>TRPG</> entrance or by finding the corresponding Covenant NPC.\n\n<Assistant_Title2>Joining Process:</>\n1. Open the Covenant selection interface.\n2. Select the Covenant you wish to join.\n3. View the abilities, faith, and recommended attributes of that Covenant.\n4. Confirm after completing attribute point allocation.\n\n<Assistant_Title3>Recommended Searches:</>{SendAnswer:[Covenant Selection and Attribute Point Allocation]|1274}"] = "<Assistant_Title1> 【Como ingressar em um Covenant】 </> \nQuando o Covenant for desbloqueado, você pode entrar no processo de adesão através da entrada <Assistant_System> TRPG </> ou encontrando o NPC do Covenant correspondente.\n\n <Assistant_Title2> Processo de adesão: </> \n1. Abra a interface de seleção do Covenant.\n2. Selecione o Pacto ao qual você deseja aderir.\n3. Veja as habilidades, fé e atributos recomendados desse Convênio.\n4. Confirme após concluir a alocação de pontos de atributo.\n\n <Assistant_Title3> Pesquisas recomendadas: </> {SendAnswer:[Covenant Selection and Attribute Point Allocation]|1274}",
  ["<Assistant_Title1>Obtaining Beyonder Materials</>\n<Assistant_Title2>Gameplay Instructions:</>\nThey can be obtained through <Assistant_Property1>World Adventure-Dungeon</>, <Assistant_Property1>War-for-War-Competition</>, <Assistant_Property1>Quest</>, <Assistant_Property1>Reimbursement Shop</>, <Assistant_Property1>Triumph Shop</>, <Assistant_Property1>Exchange Market</>, and other channels.\n<Assistant_Title3>Recommended Searches:</>{SendAnswer:[Sealed Artifact]|1265}, {SendAnswer:[Beyonder Material]|1268}, {SendAnswer:[Beyonder Material Synthesis]|1270}"] = "<Assistant_Title1> Obtenção de Beyonder Materiais </> \n <Assistant_Title2> Instruções de jogo: </> \nEles podem ser obtidos através de <Assistant_Property1> World Adventure- Masmorra </> , <Assistant_Property1> War-for-War-Competition </> , <Assistant_Property1> Missão </> , <Assistant_Property1> Loja de Reembolsos </> , <Assistant_Property1> Loja de Triunfos </> , <Assistant_Property1> Exchange Market </> e outros canais.\n <Assistant_Title3> Pesquisas recomendadas: </> {SendAnswer:[Sealed Artifact]|1265}, {SendAnswer:[ Beyonder Material]|1268}, {EnviarResposta:[ Beyonder Síntese de Materiais]|1270}",
  ["Team Channel"] = "Canal da equipe",
  ["Queuing, current position: %s"] = "Na fila, posição atual: %s",
  ["Strategy Map"] = "Mapa Estratégico",
  ["%s Win"] = "%s Ganhar",
  ["This week's auction will start in %dd %Hh %Mm %Ss"] = "O leilão desta semana começará em %d d %Hh %Mm %Ss",
  ["Agile hair curls leap in the wind, like a melodious serenade."] = "Cachos ágeis saltam ao vento, como uma serenata melodiosa.",
  ["For years, the blue silver bell in the butler's hand has faithfully performed its duty, delivering the crisp ringing to every corner of the manor."] = "Durante anos, o sino prateado azul na mão do mordomo cumpriu fielmente seu dever, transmitindo o toque nítido a todos os cantos da mansão.",
  ["Golden light intertwines with emerald radiance, light and shadow floating, chanting a silent hymn."] = "A luz dourada se entrelaça com o brilho esmeralda, luz e sombra flutuando, entoando um hino silencioso.",
  ["<Assistant_Title1>Gift of the Spirit Medium</>\n<Assistant_Title2>Achievement Category: </>Cultivation-Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Beyonder material with the <Spirit Mediumship> affix"] = "<Assistant_Title1> Dádiva do Médium Espiritual </> \n <Assistant_Title2> Categoria de conquista: </> Artefato Selado de Cultivo\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 Beyonder material com o afixo <Spirit Mediumship>",
  ["<Assistant_Title1>Gift of the Hypnotist</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the <Hypnosis> trait"] = "<Assistant_Title1> Presente do Hipnotizador </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <Hypnosis>",
  ["<Assistant_Title1>Gift of the Wind-Blessed</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the <Blessed> trait"] = "<Assistant_Title1> Presente dos Abençoados pelo Vento </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <Blessed>",
  ["<Assistant_Title1>Favor of the Avatar of Calamity</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the <avatar of Calamity> trait"] = "<Assistant_Title1> Favor do Avatar da Calamidade </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <avatar of Calamity>",
  ["<Assistant_Title1>The Fool's Divine Gift</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the {Fool} trait"] = "<Assistant_Title1> O presente divino do tolo </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato selado \n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica {Fool}",
  ["Freshly baked Star-Gazing Pie! Look at this alluring color and unique shape... Would you like to try a bite, guest?"] = "Torta recém-assada para contemplar as estrelas! Veja esta cor atraente e formato único... Gostaria de experimentar algo, convidado?",
  ["Street corner cafe, the best coffee shop in Tingen."] = "Café de esquina, a melhor cafeteria de Tingen.",
  ["Meow, purr..."] = "Miau, ronronar...",
  ["...I can understand how you feel right now; perhaps no one can understand it better than I do."] = "...Eu posso entender como você se sente agora; talvez ninguém possa entendê-lo melhor do que eu.",
  ["My feet feel a bit stiff from standing so long..."] = "Meus pés estão um pouco rígidos de tanto tempo em pé...",
  ["This job. Just. Can't go on. Really. Is."] = "Este trabalho. Apenas. Não posso continuar. Realmente. É.",
  ["Didn't Mr. Morian come here because he read that article too?"] = "O Sr. Morian não veio aqui porque leu aquele artigo também?",
  ["Mr. Azik, I have a conjecture about your condition."] = "Sr. Azik, tenho uma conjectura sobre sua condição.",
  ["(If it were a real antique, your family would have sold it long ago... this guy is quite bold, daring to lie to the police. Should I pull out my gun to scare him later?)"] = "(Se fosse uma antiguidade de verdade, sua família já a teria vendido há muito tempo... esse cara é bastante ousado, ousando mentir para a polícia. Devo sacar minha arma para assustá-lo mais tarde?)",
  ["<Assistant_Title1>【Pistol】</>\n<Assistant_Title2>Ability Characteristics: </>The pistol has moderate single-shot damage and magazine capacity, making it the most common type of firearm. \nPistols can enter aiming mode; in this state, <Assistant_Property1>shooting weak points</> can cause <Assistant_Property1>high damage</>. \n<Assistant_Title3>Recommended Search: </>{SendAnswer:[Aiming Shot]|903}, {SendAnswer:[Shooting Weak Points]|902}"] = "<Assistant_Title1> 【Pistola】 </> \n <Assistant_Title2> Características de habilidade: </> A pistola tem dano moderado de tiro único e capacidade de carregador, tornando-a o tipo de arma de fogo mais comum. \nAs pistolas podem entrar no modo de mira; neste estado, <Assistant_Property1> atirar em pontos fracos </> pode causar <Assistant_Property1> danos elevados </> . \n <Assistant_Title3> Pesquisa recomendada: </> {SendAnswer:[Aiming Shot]|903}, {SendAnswer:[Shooting Weak Points]|902}",
  ["<Assistant_Title1>【Obtaining Firearms】</>\n<Assistant_Title2>Activation Rules: </>In <Assistant_System>Story Quests</> and <Assistant_System>Sinful Tingen</>'s <Assistant_Property1>certain specific levels</>, the firearm function will be activated as the level progresses. \n<Assistant_Title3>Recommended Search: </>{SendAnswer:[Firearm Gameplay Introduction]|898}, {SendAnswer:[Aiming Shot]|903}"] = "<Assistant_Title1> 【Obtenção de armas de fogo】 </> \n <Assistant_Title2> Regras de ativação: </> Em <Assistant_System> Story Quests </> e <Assistant_System> Sinful Tingen </> <Assistant_Property1> certos níveis específicos </>, a função de arma de fogo será ativada conforme o nível avança. \n <Assistant_Title3> Pesquisa recomendada: </> {SendAnswer:[Introdução ao jogo com arma de fogo]|898}, {SendAnswer:[Aiming Shot]|903}",
  ["<Assistant_Title1>【Send You a Sevia Daisy】</>\n<Assistant_Title2>Quest Type:</><Assistant_Property2>Era Life</>\n<Assistant_Title2>Quest Description:</>Mr. Leonard asks you to help him receive the younger sister of an \"old friend\"; look for her near Blackthorn.\n<Assistant_Title2>How to Obtain:</>After your Acting level reaches <Assistant_Red>35</>, head to {Location:[Tingen(868,927)]|-13241;-7214;-1586;2;5200002;0} to trigger the quest.\n<Assistant_Title2>Quest Rewards</>: Cognition EXP, Bound Soule, Invoices, Adventure Medals, World Adventure Treasure Progress"] = "<Assistant_Title1> 【Enviar para você uma Margarida Sevia】 </> \n <Assistant_Title2> Missão Tipo: </> <Assistant_Property2> Era Life </> \n <Assistant_Title2> Missão Descrição: </> O Sr. Leonard pede que você o ajude a receber a irmã mais nova de um \"velho amigo\"; procure por ela perto de Blackthorn.\n <Assistant_Title2> Como obter: </> Depois que seu nível de atuação atingir <Assistant_Red> 35 </> , vá para {Local:[Tingen(868,927)]|-13241;-7214;-1586;2;5200002;0} para acionar o missão .\n <Assistant_Title2> Missão Recompensas </>: EXP de cognição, Soule vinculado, faturas, medalhas de aventura, progresso do tesouro de aventura mundial",
  ["<Assistant_Title1>【Bounty Value】</>\n<Assistant_Title2>Explanation: </>Participate in various events in Sinful Tingen to obtain Bounty Value, which can be accumulated to exchange for various rewards. <Assistant_Red>Weekly cap of 1000</>.\n<Assistant_Title2>Sources: </>{JumpToUI:【City of Shadows】|1302443}"] = "<Assistant_Title1> 【Bounty Value】 </> \n <Assistant_Title2> Explicação: </> Participe de vários eventos em Sinful Tingen para obter Bounty Value, que pode ser acumulado para trocar por diversas recompensas. <Assistant_Red> Limite semanal de 1.000 </> .\n <Assistant_Title2> Fontes: </> {JumpToUI:【City of Shadows】|1302443}",
  ["Rare Cocoa Milk Wine"] = "Vinho de leite de cacau raro",
  ["Season Quest"] = "Temporada Missão",
  ["The deity bestows grace, and He places the crown of the eternal night upon your head. From now on, the long night is endless, only because you stand at its end."] = "A divindade concede graça e coloca a coroa da noite eterna sobre sua cabeça. De agora em diante, a longa noite não tem fim, apenas porque você está no fim dela.",
  ["Continuous Attack."] = "Ataque Contínuo.",
  ["<Assistant_Title1>【Call of the Snowfield】</>\n<Assistant_Title2>Quest Type: </><Assistant_Property2>Life in the Era</>\n<Assistant_Title2>Quest Description: </>Under the snow that never melts, there are unknown stories hidden.\n<Assistant_Title2>How to Accept: </>After your Acting level reaches <Assistant_Red>Level 63</>, head to {Location:[Hornacis Mountain Range(406,364)]|30610;26480;-920;2;5200086;0} to trigger the quest.\n<Assistant_Title2>Quest Rewards</>: Cognitive Experience, Bound Sol, invoices, Adventure Medals, World Adventure Treasure progress"] = "<Assistant_Title1> 【Chamado do Campo de Neve】 </> \n <Assistant_Title2> Missão Tipo: </> <Assistant_Property2> Vida na Era </> \n <Assistant_Title2> Missão Descrição: </> Sob a neve que nunca derrete, há histórias desconhecidas escondidas.\n <Assistant_Title2> Como aceitar: </> Depois de seu O nível de atuação atinge <Assistant_Red> Nível 63 </>, vá para {Local:[Cordilheira Hornacis(406,364)]|30610;26480;-920;2;5200086;0} para acionar as missão .\n <Assistant_Title2> Missão Recompensas </>: Cognitivo Experiência, Bound Sol, faturas, medalhas de aventura, progresso do World Adventure Treasure",
  ["<Assistant_Title1>【Gospel of the Fool】</>\n<Assistant_Title2>Quest Type: </><Assistant_Property2>Life in the Era</>\n<Assistant_Title2>Quest Description: </>Gospel promotion of the Church of the Fool... Why would it appear in the University District?\n<Assistant_Title2>How to Accept: </>After your Acting level reaches <Assistant_Red>Level 60</>, head to {Location:[Tingen(1568,976)]|56840;-2330;-1360;2;5200002;0} to trigger the quest.\n<Assistant_Title2>Quest Rewards</>: Cognitive Experience, Bound Sol"] = "<Assistant_Title1> 【Evangelho do Louco】 </> \n <Assistant_Title2> Missão Tipo: </> <Assistant_Property2> Vida na Era </> \n <Assistant_Title2> Missão Descrição: </> Promoção do Evangelho da Igreja do Louco... Por que apareceria no Distrito Universitário?\n <Assistant_Title2> Como aceitar: </> Depois que seu nível de atuação atingir <Assistant_Red> Nível 60 </> , vá para {Location:[Tingen(1568,976)]|56840;-2330;-1360;2;5200002;0} para acionar as recompensas missão .\n <Assistant_Title2> Missão </> : Experiência Cognitiva, Bound Sol",
