  ["Compliment the reputation"] = "Elogie a reputação",
  ["Praise the weather"] = "Elogie o clima",
  ["The apocalypse is coming?"] = "O apocalipse está chegando?",
  ["Seer pathway tutor"] = "Vidente Caminho tutor",
  ["Prepare for the ritual"] = "Prepare-se para o ritual",
  ["Show concern for Enid"] = "Mostre preocupação com Enid",
  ["Compliment the youth"] = "Elogie os jovens",
  ["Tempt with money"] = "Tentar com dinheiro",
  ["Comfort kindly"] = "Conforto gentilmente",
  ["Disguise as a police officer"] = "Disfarce-se de policial",
