  ["Imperial Flag."] = "Bandeira Imperial.",
  ["Brand of Death."] = "Marca da Morte.",
  ["Bargaining."] = "Negociação.",
  ["Nightmare Impact."] = "Impacto do pesadelo.",
  ["Secret Peeking Prophecy."] = "Profecia secreta de espionagem.",
  ["Holy Light Protection."] = "Proteção da Luz Sagrada.",
  ["Ensemble Poem."] = "Poema Conjunto.",
  ["Law Judgment."] = "Julgamento Jurídico.",
  ["Berserk Gear."] = "Furioso Equipamento .",
  ["Air Cannon."] = "Canhão de ar.",
  ["Midnight Poem."] = "Poema da meia-noite.",
  ["Spirit Mediumship Ritual."] = "Ritual de Mediunidade Espiritual.",
  ["Arbitration Brand"] = "Marca de Arbitragem",
  ["Mystery Pry Gaze"] = "Olhar misterioso",
  ["Morning Light Protection"] = "Proteção contra luz matinal",
  ["Knight's Oath"] = "Juramento do Cavaleiro",
  ["Butterfly Spirit Possession"] = "Possessão do Espírito Borboleta",
  ["Death Knell Echo"] = "Eco da Sentença de Morte",
  ["Alpha Wolf Claw Combo"] = "Combinação de garras de lobo alfa",
  ["Summon a marionette transformed from a Worm of Star to unleash Miracle Card Rain, dealing damage to enemies within the target range and Stun enemies in the center of the area."] = "Evoca um Marionete transformado de Worm of Star para liberar Miracle Card Rain, causando dano aos inimigos dentro do alcance alvo e atordoando os inimigos no centro da área.",
  ["Magic Circle Visual"] = "Círculo Mágico Visual",
  ["3-person share, success 20%HP, failure mechanic kill"] = "Compartilhamento de 3 pessoas, sucesso 20% HP, falha mecânica, morte",
  ["Charge Animation"] = "Animação de carga",
  ["This is a description that can be referenced by the skill table: *s"] = "Esta é uma descrição que pode ser referenciada pela tabela de habilidades: *s",
  ["Single person"] = "Solteira",
  ["Thank you for your hard work, kind Mr./Ms. {{|}}!"] = "Obrigado pelo seu trabalho árduo, gentil Sr./Sra. {{|}}!",
  ["Please wait a moment! You are the Mr./Ms. {{|}} from Blackthorn Security Company, right? Can you do me a small favor?"] = "Por favor, espere um momento! Você é o Sr./Sra. {{|}} da Blackthorn Security Company, certo? Você pode me fazer um pequeno favor?",
  ["Branches and leaves form a soft staircase, leading me to sleep forever beneath the water..."] = "Galhos e folhas formam uma escada suave, me levando a dormir para sempre debaixo d'água...",
  ["When will Kila come back..."] = "Quando Kila voltará...",
  ["Let me help you find them."] = "Deixe-me ajudá-lo a encontrá-los.",
  ["I suffer from intermittent amnesia; I forget everything from yesterday when I wake up every day."] = "Sofro de amnésia intermitente; Esqueço tudo de ontem quando acordo todos os dias.",
  ["Oh, yes! My notebook was scattered by the wind, and the pages are floating everywhere."] = "Oh sim! Meu caderno foi espalhado pelo vento e as páginas estão flutuando por toda parte.",
  ["If that is indeed the reason, Mr./Ms. {{|}}, could I ask you to help look after this old gentleman?"] = "Se esse for realmente o motivo, Sr./Sra. {{|}}, posso pedir que você ajude a cuidar desse velho senhor?",
  ["<P_Heart>(Let him end one of the relationships to benefit three people.)</>"] = "<P_Heart> (Deixe-o terminar um dos relacionamentos para beneficiar três pessoas.) </>",
  ["The street lamps nearby suddenly broke recently, and I couldn't see anything when I left work!"] = "As lâmpadas da rua próximas quebraram repentinamente recentemente e eu não consegui ver nada quando saí do trabalho!",
  ["<P_Heart>(Sounds dangerous. I'll come take a look at night...)</>"] = "<P_Heart> (Parece perigoso. Vou dar uma olhada à noite...) </>",
  ["They don't even treat us like human beings! Ask? Asking is just a waste of effort!"] = "Eles nem nos tratam como seres humanos! Perguntar? Perguntar é apenas uma perda de esforço!",
  ["<P_Heart>(Holding forehead)</> This lamp, I'll go ask again..."] = "<P_Heart> (Segurando a testa) </> Essa lâmpada, vou perguntar de novo...",
  ["<P_Heart>(Helplessly)</> I reported it to the higher-ups, but no one has dealt with it. Sigh, they wouldn't care if we lived or died."] = "<P_Heart> (Desamparado) </> Eu relatei isso aos superiores, mas ninguém lidou com isso. Suspiro, eles não se importariam se vivêssemos ou morrêssemos.",
  ["<P_Heart>(Trembling)</> Are you sure, Mr./Ms. Witch {{|}}? He was just glowing a moment ago."] = "<P_Heart> (Tremendo) </> Tem certeza, Sr./Sra. Bruxa {{|}}? Ele estava brilhando há pouco.",
  ["You are... Mr./Ms. {{PlayerName}}{{|}}, am I right? I saw your file in the police station archives; it labels you as an expert in investigating special cases."] = "Você é... Sr./Sra. {{PlayerName}}{{|}}, estou certo? Vi seu arquivo nos arquivos da delegacia; rotula você como um especialista na investigação de casos especiais.",
  ["How is it, Mr./Ms. {{|}}? Have you seen what our recent fortunes are?"] = "Como está, Sr./Sra. {{|}}? Você viu quais são nossas fortunas recentes?",
  ["Thank you very much, Mr./Ms. {{|}}. These are our birthdays. We are all very eager to know our recent fortunes."] = "Muito obrigado, Sr./Sra. {{|}}. Estes são os nossos aniversários. Estamos todos muito ansiosos para conhecer nossa sorte recente.",
  ["Wuwu, the Goddess really heard my prayer! Kind Mr./Ms. {{|}}, may good people be under the Goddess's protection for their whole lives!"] = "Wuwu, a Deusa realmente ouviu minha oração! Gentil Sr./Sra. {{|}}, que pessoas boas fiquem sob a proteção da Deusa por toda a vida!",
  ["Really? But I don't think I misjudged it, look at that cloud..."] = "Realmente? Mas acho que não julguei mal, olhe aquela nuvem...",
  ["Sorry, Mr./Ms. {{|}}. I need to finish the preparations for sailing as soon as possible, you can find my Renny..."] = "Desculpe, Sr./Sra. {{|}}. Preciso terminar os preparativos para navegar o mais rápido possível, você pode encontrar meu Renny...",
  ["You know what I'm talking about, Mr./Ms. {{|}}. Use your meteorological instruments or something, let our Captain know we shouldn't set off today!"] = "Você sabe do que estou falando, Sr./Sra. {{|}}. Use seus instrumentos meteorológicos ou algo assim, avise nosso Capitão que não devemos partir hoje!",
  ["I'll go to Lamud Castle first to pacify Gina, then borrow money from her to see Lily. She has always satisfied all my requests."] = "Irei primeiro ao Castelo Lamud para pacificar Gina, depois pedirei dinheiro emprestado a ela para ver Lily. Ela sempre atendeu todos os meus pedidos.",
  ["But I understand what you mean, if going to one of them won't have a good result, then I'll go to both!"] = "Mas entendo o que você quer dizer, se ir em um deles não vai dar um bom resultado, então vou nos dois!",
  ["No! If I leave Lily, I will lose my love for life... If Gina leaves me, I will go crazy, I can't give up either of them."] = "Não! Se eu deixar Lily, vou perder meu amor para a vida toda... Se Gina me deixar, vou enlouquecer, não posso desistir de nenhum deles.",
  ["The results of you going to Golden Autumn Lake or Lamud Castle are not good in my divination. One should be devoted in love; it is better for you and both those young ladies."] = "Os resultados de você ir ao Golden Autumn Lake ou ao Lamud Castle não são bons no meu adivinhação. Deve-se ser devotado em amor; é melhor para você e para as duas jovens.",
  ["<P_Heart>(Better advise him.)</>"] = "<P_Heart> (É melhor aconselhá-lo.) </>",
  ["Thank you for your revelation! Gina, I'm leaving to find you now, the quiet corner of the castle is meant for us to share our hearts!"] = "Obrigado pela sua revelação! Gina, estou saindo para te encontrar agora, o canto tranquilo do castelo é feito para compartilharmos nossos corações!",
  ["<P_Heart>(Let him learn a lesson and stop his philandering.)</>"] = "<P_Heart> (Deixe-o aprender uma lição e parar de ser mulherengo.) </>",
  ["Please give me a revelation! Which place should I buy a Steam Train ticket to?"] = "Por favor, me dê uma revelação! Para qual lugar devo comprar uma passagem do Trem a Vapor?",
  ["Great Seer, <P_Yellow> Golden Autumn Lake </> and <P_Yellow> Lamud Castle </> both have people waiting for me, but my money only allows me to go to one place to keep my appointment."] = "Grande Vidente, <P_Yellow> Golden Autumn Lake </> e <P_Yellow> Lamud Castle </> ambos têm pessoas esperando por mim, mas meu dinheiro só me permite ir a um lugar para cumprir meu compromisso.",
  ["Are you... no, are you a Seer?"] = "Você é... não, você é um Vidente?",
  ["Sigh, it looks like the kids will go hungry again..."] = "Suspiro, parece que as crianças vão passar fome de novo...",
  ["When the time comes, let Gehrman enter from over there, and then directly..."] = "Quando chegar a hora, deixe Gehrman entrar por ali, e então diretamente...",
  ["Huh? You followed me here too? I have to say, this suggestion is really good."] = "Huh? Você me seguiu até aqui também? Devo dizer que esta sugestão é muito boa.",
  ["Then please feel free, I need to brainstorm here for a while."] = "Então fique à vontade, preciso debater aqui um pouco.",
  ["Then stand still, first of all—if you fall into someone's chimney again, remember to keep it a secret for me!"] = "Então, antes de mais nada, fique parado: se você cair na chaminé de alguém novamente, lembre-se de manter isso em segredo para mim!",
  ["That's great! I knew it! Getting their approval makes me happier than winning any cooking competition. This is the true \"Gold Medal Certification\"!"] = "Isso é ótimo! Eu sabia! Obter a aprovação deles me deixa mais feliz do que vencer qualquer competição de culinária. Esta é a verdadeira “Certificação Medalha de Ouro”!",
  ["How is it, how is it? What's the response to my new recipe?"] = "Como é, como é? Qual é a resposta à minha nova receita?",
  ["Do me a favor, take it for a walk around the street and help me see how everyone—especially those pickiest gourmets—reacts to it?"] = "Faça-me um favor, dê um passeio pela rua e me ajude a ver como todo mundo – especialmente os gourmets mais exigentes – reage a isso?",
  ["I've recently come up with a new dried fish recipe, using some special herbs and a smoking technique. I'm extremely satisfied with it, but it's not enough for just me to say it's good."] = "Recentemente, criei uma nova receita de peixe seco, usando algumas ervas especiais e uma técnica de defumação. Estou extremamente satisfeito com ele, mas não basta apenas eu dizer que é bom.",
  ["Oh, there's just no helping you!"] = "Oh, simplesmente não há como ajudá-lo!",
  ["As for that... she only likes good children, like those who eat their carrots properly!"] = "Quanto a isso... ela só gosta de crianças boas, daquelas que comem cenoura direito!",
  ["What's this about a haunted ancestral home you're talking about?"] = "O que é isso de casa ancestral mal-assombrada de que você está falando?",
  ["It's my family's house that has hundreds of years of history. That place is too dilapidated, and I plan to sell it for some money to subsidize my family."] = "É a casa da minha família que tem centenas de anos de história. Aquele lugar está muito degradado e pretendo vendê-lo por algum dinheiro para subsidiar minha família.",
  ["But every night, there are strange noises in the house—footsteps, sighs, and someone walking back and forth upstairs."] = "Mas todas as noites há ruídos estranhos na casa – passos, suspiros e alguém andando de um lado para outro escada acima.",
  ["I'm the only one in the house, so the one making the noise must be... something unclean!"] = "Eu sou o único na casa, então quem está fazendo barulho deve ser...algo impuro!",
  ["<P_Heart>(Something unclean? It might be Beyonder power, go take a look with him.)</>"] = "<P_Heart> (Algo impuro? Pode ser Beyonder poder, vá dar uma olhada com ele.) </>",
  ["Maybe I can help; why don't you let me try?"] = "Talvez eu possa ajudar; por que você não me deixa tentar?",
  ["You... you can drive that thing out? That's great! Let's go, follow me quickly!"] = "Você... você pode expulsar essa coisa? Isso é ótimo! Vamos, siga-me rapidamente!",
  ["William Heywood, the host of this ball, doesn't look like a real host. His face in his early thirties should have been heroic, but there is a faint layer of fatigue between his brows."] = "William Heywood, o anfitrião deste baile, não parece um verdadeiro anfitrião. Seu rosto de trinta e poucos anos deveria ser heróico, mas há uma leve camada de fadiga entre suas sobrancelhas.",
  ["Mind you, this isn't just idle social chatter about the weather—"] = "Veja bem, isso não é apenas conversa fiada sobre o tempo—",
  ["I've been cursed! I can't get up from the ground, only a true love's kiss can break it!"] = "Eu fui amaldiçoado! Não consigo me levantar do chão, só um beijo de amor verdadeiro pode quebrá-lo!",
  ["Yeah, why... why did I do it?"] = "Sim, por que... por que eu fiz isso?",
  ["This exhausted her strength, forcing her to fall into a deep sleep, but even now, she is guarding us from the shadows."] = "Isso esgotou suas forças, forçando-a a cair em um sono profundo, mas mesmo agora ela está nos protegendo das sombras.",
  ["Besides the craft brewery, you can also try building different types of workshops to meet the needs of different orders."] = "Além da cervejaria artesanal, você também pode tentar construir diversos tipos de oficinas para atender às necessidades dos diversos pedidos.",
  ["She was born in the night, and with two snaps of her fingers, this town was built."] = "Ela nasceu durante a noite e com dois estalar de dedos esta cidade foi construída.",
  ["This Mr./Ms. {{|}}, do you know Godot?"] = "Este Sr./Sra. {{|}}, você conhece Godot?",
  ["At that time, the malt ale Thomas brewed was so fragrant it could lure drunks from the next town over. Eleanor's pies were also a specialty, the crust was so flaky it would crumble with one bite."] = "Naquela época, a malt ale que Thomas preparava era tão perfumada que poderia atrair bêbados da cidade vizinha. As tortas de Eleanor também eram uma especialidade, a crosta era tão escamosa que se esfarelava com uma mordida.",
  ["The Baron is looking at that corner. What's there?"] = "O Barão está olhando para aquele canto. O que há?",
  ["Look at the craftsmanship of these goods, truly retro, truly aristocratic aesthetic!"] = "Veja o artesanato desses produtos, uma estética verdadeiramente retrô e verdadeiramente aristocrática!",
  ["Susie's identity allowed her to avoid many troubles. When we are at a loss for what to do, Susie just says—'I don't know, after all, I'm just a dog'."] = "A identidade de Susie permitiu-lhe evitar muitos problemas. Quando não sabemos o que fazer, Susie apenas diz: 'Não sei, afinal sou apenas um cachorro'.",
  ["<P_Heart>(Spreads hands)</> So, we are of the same generation. She should also call you Uncle/Aunt {{|}}."] = "<P_Heart> (Abre as mãos) </> Então, somos da mesma geração. Ela também deveria chamar você de tio/tia {{|}}.",
  ["Don't worry, it's just a photo. It's a memento for myself, and also a gift of gratitude the crow wanted to give you."] = "Não se preocupe, é apenas uma foto. É uma lembrança para mim e também um presente de gratidão que o corvo quis lhe dar.",
  ["What's there to be afraid of? I wouldn't play any pranks, at least not now."] = "O que há para ter medo? Eu não faria nenhuma pegadinha, pelo menos não agora.",
  ["So straightforward? Aren't you afraid I'll take pictures of something I shouldn't?"] = "Tão simples? Você não tem medo que eu tire fotos de algo que não deveria?",
  ["Mr./Ms. {{|}}, how is the pocket watch?"] = "Sr./Sra. {{|}}, como está o relógio de bolso?",
  ["It's right here!"] = "Está bem aqui!",
  ["The promised moment has arrived, my listener, and witness to this history."] = "Chegou o momento prometido, meu ouvinte e testemunha desta história.",
  ["This quest always makes me feel uneasy, my little Rozanne, the person I worry about the most."] = "Isso missão sempre me deixa desconfortável, minha pequena Rozanne, a pessoa com quem mais me preocupo.",
  ["Sob sob..."] = "Sozinho, soluço...",
  ["You're the idiot! Mother never lied to me; my wish will come true."] = "Você é o idiota! Mamãe nunca mentiu para mim; meu desejo se tornará realidade.",
  ["Wipe the Mirror"] = "Limpe o espelho",
  ["My Lord calls himself \"The Fool.\" In the past, in the present, and in the future, he is the great ruler who dominates the Spirit World, the King of Yellow and Black who wields good luck, and the beacon for every living being seeking eternity."] = "Meu Senhor se autodenomina \"O Louco\". No passado, no presente e no futuro, ele é o grande governante que domina o Mundo Espiritual, o Rei do Amarelo e do Preto que exerce a boa sorte e o farol para todo ser vivo que busca a eternidade.",
  ["Beyonders of the Spectator pathway can not only perform psychotherapy but also use mind control to make Beyonders collapse."] = "Beyonders do Espectador Caminho pode não apenas realizar psicoterapia, mas também usar o controle da mente para fazer Beyonders entrar em colapso.",
  ["What? Ms. Susie is invisible?"] = "O que? Dona Susie é invisível?",
  ["For example, you can't see Susie now, but she is indeed lying at your feet enjoying her nap time."] = "Por exemplo, você não pode ver Susie agora, mas ela realmente está deitada a seus pés, aproveitando a soneca.",
  ["The Sequence name “Spectator” makes people mistakenly think this is a pathway only good at observation and support. But in reality, this is also a disguise, a disguise that makes people underestimate the enemy even more."] = "O nome Sequência “Espectador” faz as pessoas pensarem erroneamente que este é um Caminho bom apenas para observação e apoio. Mas, na realidade, isto também é um disfarce, um disfarce que faz com que as pessoas subestimem ainda mais o inimigo.",
  ["My first successful investment was in the stocks of a bicycle company. I didn't have enough money to buy the stocks at the time, but my father taught me an investment technique."] = "Meu primeiro investimento bem-sucedido foi em ações de uma empresa de bicicletas. Eu não tinha dinheiro suficiente para comprar ações na época, mas meu pai me ensinou uma técnica de investimento.",
  ["I cannot give you a sum of money directly every time, but I can tell you how to invest. Emperor Roselle said, giving someone a fish is not as good as teaching them how to fish!"] = "Não posso lhe dar uma quantia em dinheiro diretamente todas as vezes, mas posso lhe dizer como investir. O Imperador Roselle disse que dar um peixe a alguém não é tão bom quanto ensiná-lo a pescar!",
  ["Anyway! If you lack money in the future, you can come to me."] = "De qualquer forma! Se você não tiver dinheiro no futuro, pode vir até mim.",
  ["Miss Audrey, why can Ms. Susie talk? Is she... a magical creature?"] = "Senhorita Audrey, por que a Sra. Susie pode falar? Ela é... uma criatura mágica?",
  ["Understood, thank you. I have learned some more Beyonder knowledge."] = "Entendido, obrigado. Aprendi mais alguns Beyonder conhecimentos.",
  ["A three-part honorific name is not just a name; it is closer to a gaze of divinity, a spell for summoning."] = "Um nome honorífico de três partes não é apenas um nome; está mais próximo de um olhar de divindade, um feitiço para convocação.",
  ["In the Extraordinary world, chanting unknown honorific names is very likely to summon unknown dangers. Except for the honorific names of the True Gods and your Tarot Club companions, you must not chant any other honorific names."] = "No mundo Extraordinário, entoar nomes honoríficos desconhecidos provavelmente evocará perigos desconhecidos. Exceto pelos nomes honoríficos dos Deuses Verdadeiros e seus Clube do Tarô companheiros, você não deve cantar nenhum outro nome honorífico.",
  ["So your second line of the honorific name is the Blessed of the King of Yellow and Black."] = "Portanto, sua segunda linha do nome honorífico é Abençoado do Rei do Amarelo e do Preto.",
  ["My honorific name is—The Holy Spirit who sees all, the Blessed of the King of Yellow and Black, the traveler of dreams and hearts."] = "Meu nome honorífico é – O Espírito Santo que tudo vê, o Abençoado do Rei Amarelo e Preto, o viajante dos sonhos e dos corações.",
  ["Miss Audrey, do you have an honorific name? If I want to pray to you for help, what should I chant?"] = "Senhorita Audrey, você tem um nome honorífico? Se eu quiser orar pedindo ajuda, o que devo cantar?",
  ["These peddlers specialize in scamming passersby. Mr./Ms. {{|}}, don't pay attention to him."] = "Esses vendedores ambulantes são especializados em enganar os transeuntes. Sr./Sra. {{|}}, não preste atenção nele.",
  ["Mr./Ms. {{|}}, look at this! Tableware used by the first Baron Lamud! 50 pounds!"] = "Sr./Sra. {{|}}, olha isso! Talheres usados ​​pelo primeiro Barão Lamud! 50 libras!",
  ["But he/she {{|}} is right. My grandmother passed away ten years ago, but I always feel like she's there—airing out the quilts on a nice day, and when the wind blows, it's like she's patting my head."] = "Mas ele/ela {{|}} está certo. Minha avó faleceu há dez anos, mas sempre sinto que ela está lá, arejando as colchas em um dia bonito, e quando o vento sopra, é como se ela estivesse dando tapinhas na minha cabeça.",
  ["<P_Heart> (Looks at you) </> You've learned very well! Young man/woman {{|}}!"] = "<P_Heart> (Olha para você) </> Você aprendeu muito bem! Jovem/mulher {{|}}!",
  ["Let's go. Take your \"darling,\" thank this brother/sister {{|}} who helped me find you, and let's go home."] = "Vamos. Pegue seu “querido”, agradeça a esse irmão/irmã {{|}} que me ajudou a encontrar você e vamos para casa.",
  ["Welcome to Heywood Manor, Mr./Ms. {{PlayerName}}{{|}}. Please enter; the ball is about to begin."] = "Bem-vindo ao Heywood Manor, Sr./Sra. {{PlayerName}}{{|}}. Por favor entre; a bola está prestes a começar.",
  ["I admit it... it was me. I was the one who murdered the master."] = "Eu admito... fui eu. Fui eu quem assassinou o mestre.",
  ["His eyes occasionally scan in a certain direction—not looking at people, as if confirming something."] = "Seus olhos ocasionalmente examinam uma determinada direção – sem olhar para as pessoas, como se confirmassem algo.",
  ["As for why she can talk, it stems from... a small mistake, a small error that all dog owners make: forgetting that their dog can open doors."] = "Quanto ao motivo pelo qual ela consegue falar, isso se deve a... um pequeno erro, um pequeno erro que todos os donos de cães cometem: esquecer que seu cachorro pode abrir portas.",
  ["<P_Heart> (This Mr./Ms. {{|}} I just met has been looking at me since just now, could it be—) </>"] = "<P_Heart> (Este Sr./Sra. {{|}} que acabei de conhecer está olhando para mim desde agora, poderia ser—) </>",
  ["Actually, only a True God can use a three-part honorific name. The honorific names of me and other Tarot Club companions borrow the True God status of Mr. Fool."] = "Na verdade, apenas um Deus Verdadeiro pode usar um nome honorífico de três partes. Os nomes honoríficos meus e de outros Clube do Tarô companheiros emprestam o status de Deus Verdadeiro do Sr.",
  ["Please step away from the current clamor and come to my side."] = "Por favor, afaste-se do clamor atual e venha para o meu lado.",
  ["Used to?"] = "Costumava ser?",
  ["Let's not talk about these old matters, Mr./Ms. {{|}}, don't let these affect your appreciation of the scenery at the foot of the mountain."] = "Não vamos falar sobre esses assuntos antigos, Sr./Sra. {{|}}, não deixe que isso afete sua apreciação da paisagem no sopé da montanha.",
  ["I'll give it a try."] = "Vou tentar.",
  ["Perhaps it has a connection to the royal family, or perhaps it's an admirer of the Earl of Lasting, what do you think?"] = "Talvez tenha ligação com a família real, ou talvez seja um admirador do Conde de Lasting, o que você acha?",
  ["As the only high-end department store in Tingen, we have never known who the investor behind it is."] = "Sendo a única loja de departamentos sofisticada em Tingen, nunca soubemos quem é o investidor por trás dela.",
  ["That is the war that happened after the Twenty-Year War and before the War of the Oath-Breakers. It allowed Loen to defeat Intis and become strong again!"] = "Essa é a guerra que aconteceu depois da Guerra dos Vinte Anos e antes da Guerra dos Quebradores do Juramento. Isso permitiu que Loen derrotasse Intis e se tornasse forte novamente!",
  ["I've wanted to share this discovery with someone for a long time! Do you know about the Rose War?"] = "Há muito tempo queria compartilhar essa descoberta com alguém! Você sabe sobre a Guerra das Rosas?",
  ["This is the most high-end department store in all of Tingen; even when it's closed, many people are watching it!"] = "Esta é a loja de departamentos mais sofisticada de toda Tingen; mesmo quando está fechado, muitas pessoas estão assistindo!",
  ["Harold Department Store is not open, why is there still security?"] = "A loja de departamentos Harold não está aberta, por que ainda há segurança?",
  ["Doing volunteer work can balance our labor contributions, and she and I no longer argue because of this."] = "Fazer trabalho voluntário pode equilibrar nossas contribuições trabalhistas, e ela e eu não discutimos mais por causa disso.",
  ["As a believer of the Goddess, I cannot go against my own thoughts of equality."] = "Como crente na Deusa, não posso ir contra os meus próprios pensamentos de igualdade.",
  ["A believer of the Storm, huh..."] = "Um crente na Tempestade, hein...",
  ["Don't misunderstand, it's not that she thinks I don't clean well; my wife is a believer of the Storm."] = "Não entenda mal, não é que ela pense que eu não limpo bem; minha esposa acredita na Tempestade.",
  ["Your previous adventure experience must be very rich, aren't you considering re-experiencing an exciting life?"] = "Sua experiência anterior de aventura deve ser muito rica, você não está pensando em reviver uma vida emocionante?",
  ["Never mind, sorry to bother you."] = "Não importa, desculpe incomodá-lo.",
  ["Hello Mr./Ms. {{|}}, are you looking for a divination, or do you want to join our Club?"] = "Olá Sr./Sra. {{|}}, você está procurando um adivinhação ou quer se juntar ao nosso Clube?",
  ["“His” help?"] = "“Sua” ajuda?",
  ["Haha, I'd love to meet this gentleman if I get the chance!"] = "Haha, adoraria conhecer esse senhor se tiver oportunidade!",
  ["It was an instructor named Azik. We were very close. It's been so long since we last spoke; I wonder how he's doing."] = "Era um instrutor chamado Azik. Estávamos muito próximos. Já faz muito tempo desde a última vez que nos falamos; Eu me pergunto como ele está.",
  ["You came late; that was a few years ago."] = "Você chegou atrasado; isso foi há alguns anos.",
  ["Oh? Was there an opponent on par with you, Professor?"] = "Oh? Havia um oponente no mesmo nível que você, professor?",
  ["A long time ago, there was a guy who would always argue with me until his face turned red... That's a distant memory now."] = "Há muito tempo atrás, havia um cara que sempre discutia comigo até ficar com o rosto vermelho... Essa é uma memória distante agora.",
  ["Professor Cohen is very rigorous academically, and I am very happy to chat with him about my ideas."] = "O professor Cohen é muito rigoroso academicamente e fico muito feliz em conversar com ele sobre minhas ideias.",
  ["Debate? Haha, it's just me exchanging some research with my student; it doesn't quite qualify as a debate."] = "Debate? Haha, sou só eu trocando algumas pesquisas com meu aluno; não se qualifica exatamente como um debate.",
  ["Hello, young man. I see you've been here for a while; would you like to join the discussion?"] = "Olá, jovem. Vejo que você está aqui há algum tempo; você gostaria de participar da discussão?",
  ["Aston, I believe you understand that the Church has its own stance. It is very difficult to filter that out..."] = "Aston, acredito que você entende que a Igreja tem sua própria postura. É muito difícil filtrar isso...",
  ["But Professor, only church classics contain more records about the War of the Four Emperors. Finding common truths in the literature might be more likely..."] = "Mas professor, apenas os clássicos da igreja contêm mais registros sobre a Guerra dos Quatro Imperadores. Encontrar verdades comuns na literatura pode ser mais provável...",
  ["There is too much uncertainty regarding the history of the Fourth Epoch. You should start your research from existing relics to eliminate uncertain factors."] = "Há muita incerteza em relação à história da Quarta Época. Você deve começar sua pesquisa a partir de relíquias existentes para eliminar fatores incertos.",
  ["Over-word-limit elaborate burial"] = "Enterro elaborado com limite de palavras",
  ["It's alright. No matter when, I am always willing to introduce you to my Lord, the great Mr. Fool."] = "Está tudo bem. Não importa quando, estou sempre disposto a apresentá-lo ao meu Senhor, o grande Sr.",
  ["High-ranking yet philanthropic and open-minded. Praise my Lord!"] = "Alto escalão, mas filantrópico e de mente aberta. Louvado seja meu Senhor!",
  ["He cares for every living being, even if you don't believe in \"The Fool,\" you can still enjoy everything of the Tarot Club."] = "Ele se preocupa com todos os seres vivos, mesmo que você não acredite em \"O Louco\", você ainda pode aproveitar tudo do Clube do Tarô .",
  ["My Lord will not force people to convert, nor does he mind if the faith is pure. Simply put, he doesn't mind if people believe in him while believing in other gods."] = "Meu Senhor não forçará as pessoas a se converterem, nem se importa se a fé for pura. Simplificando, ele não se importa se as pessoas acreditam nele enquanto acreditam em outros deuses.",
  ["Mr. “Fool” is merciful and compassionate, the savior of this world, yet he lets us address him as “he” rather than “He”."] = "O Sr. “Tolo” é misericordioso e compassivo, o salvador deste mundo, mas ele nos permite tratá-lo como “ele” em vez de “Ele”.",
  ["Mr. “Fool” is a true God recognized by all churches, and the successful construction of the Tarot Club is also thanks to his help."] = "O Sr. “Tolo” é um Deus verdadeiro reconhecido por todas as igrejas, e o sucesso da construção do Clube do Tarô também se deve à sua ajuda.",
  ["My Lord saved the lost city-state abandoned by the gods, led the survivors of that continent out of the \"Forsaken Land of the Gods,\" and rebuilt their home on the island..."] = "Meu Senhor salvou a cidade-estado perdida abandonada pelos deuses, conduziu os sobreviventes daquele continente para fora da “Terra Abandonada dos Deuses” e reconstruiu sua casa na ilha…",
  ["The “Angel of Punishment”, He is the Lord's thunder, the Lord's wrath, the Lord's palm, and the judge and executioner of all the fallen and the unclean."] = "O “Anjo do Castigo”, Ele é o trovão do Senhor, a ira do Senhor, a palma do Senhor, e o juiz e executor de todos os caídos e impuros.",
  ["My Lord dwells above reality and the Spirit World, his mercy fills the heavens and the earth, and there are six Angels standing by his side..."] = "Meu Senhor habita acima da realidade e do Mundo Espiritual, sua misericórdia enche os céus e a terra, e há seis Anjos ao seu lado...",
  ["Simulated Acting · Bard"] = "Atuação Simulada · Bardo",
  ["The day I concocted the potion, Susie opened the door and entered the laboratory, licking a portion of the Spectator potion. Fortunately, I had prepared two sets of materials at the time."] = "No dia em que preparei a poção, Susie abriu a porta e entrou no laboratório, lambendo uma porção da poção do Espectador. Felizmente, preparei dois conjuntos de materiais na época.",
  ["Acting · Bard"] = "Atuação · Bardo",
  ["The War of the Roses?"] = "A Guerra das Rosas?",
  ["Go ahead, my true love is... *snore*, *snort*..."] = "Vá em frente, meu verdadeiro amor é... *ronco*, *bufo*...",
  ["Sigh, shall I go find your true love then?"] = "Suspiro, devo encontrar seu verdadeiro amor então?",
  ["You ask very tricky questions. You're not very good at chatting."] = "Você faz perguntas muito complicadas. Você não é muito bom em conversar.",
  ["Tomorrow is my wedding day, and Emilia, my beautiful witch of a fiancée, is surely going to be angry again—"] = "Amanhã é o dia do meu casamento, e Emilia, minha linda noiva bruxa, certamente ficará com raiva de novo...",
  ["We cannot. We are not going anywhere."] = "Não podemos. Não vamos a lugar nenhum.",
  ["Perhaps. Yesterday, today, tomorrow—I haven't been keeping track."] = "Talvez. Ontem, hoje, amanhã – não tenho acompanhado.",
  ["……Have you been waiting for a long time?"] = "...... Você está esperando há muito tempo?",
  ["And so, we gather here."] = "E então, nos reunimos aqui.",
  ["He said the train in Backlund is very long, and you can go all the way to the Snowy Mountain."] = "Ele disse que o trem em Backlund é muito longo e você pode ir até a Montanha Nevada.",
  ["He said Tingen has a University District, and you can fly above the clouds by taking an airship."] = "Ele disse que Tingen tem um distrito universitário e que você pode voar acima das nuvens em uma aeronave.",
  ["He said the outside world is very big."] = "Ele disse que o mundo exterior é muito grande.",
  ["<P_Heart>(They are giving that girl a hard time? Go up and help her!)</>"] = "<P_Heart> (Eles estão incomodando aquela garota? Suba e ajude-a!) </>",
  ["Hmm? Nothing. Something's wrong, try activating spirit vision."] = "Hum? Nada. Algo está errado, tente ativar Visão Espiritual .",
  ["<P_Heart>(He is pretending to be a mushroom!)</>"] = "<P_Heart> (Ele está fingindo ser um cogumelo!) </>",
  ["<P_Heart>(His eyeballs are moving slightly; he is thinking about something, and he is very clear-headed.)</>"] = "<P_Heart> (Seus globos oculares estão se movendo ligeiramente; ele está pensando em algo e está muito lúcido.) </>",
  ["<P_Heart>(Let me see, he is holding his head with both hands, his chin buried in his knees, as if resisting the outside world.)</>"] = "<P_Heart> (Deixe-me ver, ele está segurando a cabeça com as duas mãos, o queixo enterrado nos joelhos, como se estivesse resistindo ao mundo exterior.) </>",
  ["<P_Heart>(He stopped talking...)</>"] = "<P_Heart> (Ele parou de falar...) </>",
  ["We all feel sorry for her, but what can we say? As long as she is happy."] = "Todos sentimos pena dela, mas o que podemos dizer? Contanto que ela esteja feliz.",
  ["Now she always says Thomas is still here, sitting right next to her. Sometimes she even pours ale for the empty seat, saying Thomas loves this drink..."] = "Agora ela sempre diz que Thomas ainda está aqui, sentado ao lado dela. Às vezes ela até serve cerveja para o lugar vazio, dizendo que Thomas adora essa bebida...",
  ["Sigh, after Thomas passed away, Eleanor's hair turned gray overnight."] = "Suspiro, depois que Thomas faleceu, o cabelo de Eleanor ficou grisalho durante a noite.",
  ["Then now..."] = "Então agora...",
  ["Thomas loved to tell jokes, and Eleanor would laugh behind the counter, unable to even hold the cup in her hand... tsk tsk, at that time, it was so good."] = "Thomas adorava contar piadas, e Eleanor ria atrás do balcão, sem conseguir nem segurar o copo na mão... tsk tsk, naquela hora era tão bom.",
  ["The best souvenir in Lamud Town! Mr./Ms. {{|}}, this is the best choice for picking gifts for your family and friends!"] = "A melhor lembrança da cidade de Lamud! Sr./Sra. {{|}}, esta é a melhor opção para escolher presentes para sua família e amigos!",
  ["What is the \"Mysterious Prophecy of Golden Autumn Lake\" you just mentioned?"] = "Qual é a “Profecia Misteriosa do Lago Dourado do Outono” que você acabou de mencionar?",
  ["Cyril, give me more time... Alright, don't let down the scenery of Golden Autumn Lake, let us temporarily forget everything in Backlund."] = "Cyril, me dê mais tempo... Tudo bem, não decepcione a paisagem do Golden Autumn Lake, vamos esquecer temporariamente tudo em Backlund.",
  ["Oh, then he should work at the Backlund court, not inherit a publishing house."] = "Ah, então ele deveria trabalhar na corte de Backlund, e não herdar uma editora.",
  ["He always says that punctuation should be as rigorous as a marriage contract."] = "Ele sempre diz que a pontuação deve ser tão rigorosa quanto um contrato de casamento.",
  ["Branches and leaves form soft steps, letting me walk toward the long sleep at the bottom of the water..."] = "Galhos e folhas formam passos suaves, deixando-me caminhar em direção ao longo sono no fundo da água...",
  ["The fried eggs at this place are the best..."] = "Os ovos fritos deste lugar são os melhores...",
  ["When will Gila come back..."] = "Quando Gila vai voltar...",
  ["The weather is very bad, a blizzard will definitely arrive within half an hour!"] = "O tempo está muito ruim, uma nevasca com certeza chegará em meia hora!",
  ["Why can't we?"] = "Por que não podemos?",
  ["My dear, why do I remember that Emperor Roselle wrote the same poem?"] = "Minha querida, por que me lembro que o Imperador Roselle escreveu o mesmo poema?",
  ["“Tired, sitting by the roadside, taking this book out……”"] = "“Cansado, sentado na beira da estrada, tirando este livro…”",
  ["“When you are old and grey and full of sleep.”"] = "“Quando você estiver velho, grisalho e cheio de sono.”",
  ["Rozanne has become talkative again recently; she has been training the new clerk very well."] = "Rozanne voltou a falar recentemente; ela tem treinado muito bem o novo funcionário.",
  ["Rather than satisfying requirements, she needs someone who can understand her to be by her side."] = "Em vez de satisfazer os requisitos, ela precisa de alguém que possa entendê-la ao seu lado.",
  ["Rozanne will have a good husband who can accompany her and satisfy all her requirements, the kind who can even drink coffee with pepper added!"] = "Rozanne terá um bom marido que poderá acompanhá-la e satisfazer todas as suas necessidades, do tipo que pode até tomar café com pimenta!",
  ["Today Rozanne became friends with a girl who came to make a request, and they even made an appointment to go shopping on their day off."] = "Hoje Rozanne ficou amiga de uma garota que veio fazer um pedido, e eles até marcaram para fazer compras no dia de folga.",
  ["If something happens to me, I hope everyone can help take care of my daughter and guard her happiness."] = "Se algo acontecer comigo, espero que todos possam ajudar a cuidar da minha filha e a proteger sua felicidade.",
  ["As a Nighthawk guarding Tingen, I cannot go home on time every day to tell her bedtime stories, I can only pray to the Goddess, wishing her a sweet dream."] = "Como Vigia Noturno guardando Tingen, não posso ir para casa na hora todos os dias para contar suas histórias de dormir, só posso rezar para a Deusa, desejando-lhe um bom sonho.",
  ["I'm here."] = "Estou aqui.",
  ["Here for a drink? We aren't open yet, but I can let you have a taste first."] = "Está aqui para tomar uma bebida? Ainda não estamos abertos, mas posso deixar você provar primeiro.",
  ["Afraid of what? I'm not going to play any pranks, at least not now."] = "Medo de quê? Não vou pregar nenhuma peça, pelo menos não agora.",
  ["Thank you, Magician {Mr.{Ms.|}}."] = "Obrigado, Mágico {Sr.{Sra.|}}.",
  ["This {Mr.|Ms.}, please don't mind her, it's no use talking to her."] = "Este {Sr. | Sra.}, por favor, não ligue para ela, não adianta falar com ela.",
  ["Goodbye, warm {Mr.|Ms.}!"] = "Adeus, caloroso {Sr. | Sra.}!",
  ["Thank you, {Mr.|Ms.}. Emily is rarely this happy."] = "Obrigado, {Sr. | Sra.}. Emily raramente fica tão feliz.",
  ["<P_Heart>(Shaking head) </>No, this time let this {Mr.|Ms.} write it. Is that okay?"] = "<P_Heart> (Balançando a cabeça) </> Não, desta vez deixe este {Sr.|Sra.} escrever. Tudo bem?",
  ["Sorry, {Mr.|Ms.}. My daughter... she can't see."] = "Desculpe, {Sr.|Sra.}. Minha filha... ela não pode ver.",
  ["Bo-bo-boss! It's {him{her|}}! The one who always ruins our good deeds!"] = "Bo-bo- chefe ! É {ele{ela|}}! Aquela que sempre estraga nossas boas ações!",
  ["Towards the station! Th-thank you, kind {Mr.{Ms.|}}..."] = "Em direção à estação! O-obrigado, gentil {Sr.{Sra.|}}...",
  ["{Mr.{Ms.|}}, thank you for helping me find these back. I will write all of this down."] = "{Sr.{Sra.|}}, obrigado por me ajudar a encontrar isso de volta. Vou anotar tudo isso.",
  ["The appointed time has arrived, my listener, and witness to this history."] = "Chegou a hora marcada, meu ouvinte e testemunha desta história.",
  ["The 'Tingen Honest Man' says our safety regulations are like the fake beards in an opera house—good to look at but useless."] = "O “Homem Honesto de Tingen” diz que as nossas normas de segurança são como as barbas postiças numa casa de ópera – boas de se ver, mas inúteis.",
  ["Admiral of Iceberg's ship? I've heard some rumors."] = "Almirante do navio do Iceberg? Eu ouvi alguns rumores.",
  ["I recently figured out a new recipe for dried fish, using some special herbs and smoking techniques. I am extremely satisfied with it, but it's not enough for just me to say it's good."] = "Recentemente descobri uma nova receita de peixe seco, usando algumas ervas especiais e técnicas de defumação. Estou extremamente satisfeito com ele, mas não basta apenas eu dizer que é bom.",
  ["Oh, yes! My notebook was blown away by the wind, and the pages are floating everywhere."] = "Oh sim! Meu caderno foi levado pelo vento e as páginas estão flutuando por toda parte.",
  ["Night! Again!"] = "Noite! De novo!",
  ["Will surely reveal a pure smile to the dead:"] = "Certamente revelará um sorriso puro aos mortos:",
  ["Finally, the boss chopped off its head, climbed to the highest point, and became the great dragon hunter!"] = "Finalmente, o chefe cortou sua cabeça, subiu ao ponto mais alto e se tornou o grande caçador de dragões!",
  ["Did you come here when you were a child?"] = "Você veio aqui quando era criança?",
  ["Wuu wuu... {Mr.{Ms.|}}, what should I do?"] = "Wuu wuu... {Sr.{Sra.|}}, o que devo fazer?",
  ["Cough, cough... {Mr.{Ms.|}}, I'm back, I've reached the exit..."] = "Tosse, tosse... {Sr.{Sra.|}}, estou de volta, cheguei à saída...",
  ["No, {Mr.{Ms.|}}, we were bought by him from the poorhouse... I don't want to go back to a place like that. They only care about selling children; they don't care at all what kind of person they're selling them to!"] = "Não, {Sr.{Sra.|}}, fomos comprados por ele no asilo... Não quero voltar para um lugar como esse. Eles só se preocupam em vender crianças; eles não se importam com o tipo de pessoa para quem os estão vendendo!",
  ["But if I can't earn money, Jem will die. {Mr.{Ms.|}}, he will die, what should I do..."] = "Mas se eu não conseguir ganhar dinheiro, o Jem morrerá. {Sr.{Sra.|}}, ele vai morrer, o que devo fazer...",
  ["Buried with honors for exceeding the word count"] = "Enterrado com honras por exceder a contagem de palavras",
  ["Today's sunset is perfect for painting. I have to go back, {Mr.{Ms.|}}, goodbye."] = "O pôr do sol de hoje é perfeito para pintar. Eu tenho que voltar, {Sr.{Sra.|}}, adeus.",
  ["When you observe something thousands of times, it naturally leaves a voice in your heart. This isn't madness, {Mr.{Ms.|}}, this is just... familiarity."] = "Quando você observa algo milhares de vezes, isso naturalmente deixa uma voz em seu coração. Isso não é loucura, {Sr.{Sra.|}}, isso é apenas... familiaridade.",
  ["This Mr. Da Vinci and this {Mr.{Ms.|}}!"] = "Este Sr. Da Vinci e esta {Sr.{Sra.|}}!",
  ["Is that really okay? {Mr.{Ms.|}}, why are you helping me like this?"] = "Isso está realmente bem? {Sr.{Sra.|}}, por que você está me ajudando assim?",
  ["Hey {Mr.{Ms.|}}! Want to try a drink that bites your tongue? Only 1 penny, punchier than sweet iced tea, and more refreshing than ginger beer!"] = "Ei, {Sr.{Sra.|}}! Quer experimentar uma bebida que morde a língua? Apenas 1 centavo, mais forte que o chá gelado doce e mais refrescante que a cerveja de gengibre!",
  ["We will come again tomorrow until every heartfelt gift has been delivered. I hope that when they receive them, they can feel a little bit of happiness. Kind {Mr.{Ms.|}}, may the Goddess bless you."] = "Voltaremos amanhã até que todos os presentes sinceros sejam entregues. Espero que ao recebê-los possam sentir um pouco de felicidade. Gentil {Sr.{Sra.|}}, que a Deusa o abençoe.",
  ["Nothing."] = "Nada.",
  ["Stop, {Mr.{Ms.|}}... Please forgive my rudeness, but you cannot approach here for the time being."] = "Pare, {Sr.{Sra.|}}... Por favor, perdoe minha grosseria, mas você não pode se aproximar aqui por enquanto.",
  ["{Mr.{Ms.|}}, it's you. The return for the goods you bought was successful, and the payment has been recovered."] = "{Sr.{Sra.|}}, é você. A devolução dos produtos que você comprou foi bem-sucedida e o pagamento foi recuperado.",
  ["My goodness, {he{she|}} makes it sound even more reasonable!"] = "Meu Deus, {ele{ela|}} faz com que pareça ainda mais razoável!",
  ["{Mr.{Ms.|}}, these two people are members of a scam gang that has been roaming around Tingen recently. You haven't been deceived, have you?"] = "{Sr.{Sra.|}}, essas duas pessoas são membros de uma gangue fraudulenta que tem perambulado por Tingen recentemente. Você não foi enganado, não é?",
  ["Thank you! Kind {Mr.{Ms.|}}."] = "Obrigado! Gentil {Sr.{Sra.|}}.",
  ["Respected {Mr.{Ms.|}}, excuse me for a moment. I wonder if you have a special fondness for history and art? I have an exceptionally unique manor on my hands, and I am looking for someone fated to inherit its story."] = "Respeitado {Sr.{Sra.|}}, com licença por um momento. Será que você tem um carinho especial por história e arte? Tenho uma mansão excepcionalmente única em mãos e estou procurando alguém destinado a herdar sua história.",
  ["But I don't understand, {Mr.{Ms.|}}, don't you think love is just the trickery of fate? How can there be such an absurd thing as love at first sight, making people willing to give everything for a stranger?"] = "Mas eu não entendo, {Sr.{Sra.|}}, você não acha que o amor é apenas uma artimanha do destino? Como pode existir uma coisa tão absurda como o amor à primeira vista, fazendo com que as pessoas estejam dispostas a dar tudo por um estranho?",
  ["In any case, {Mr.{Ms.|}}, how much are you willing to pay for this music box?"] = "De qualquer forma, {Sr.{Sra.|}}, quanto você está disposto a pagar por esta caixa de música?",
  ["{Mr.{Ms.|}}, have you never heard of it? It's that—"] = "{Sr.{Sra.|}}, você nunca ouviu falar disso? É isso—",
  ["Oh, forget it! {Mr.{Ms.|}}, please be careful, try to stall him as much as possible, I'll go to the nearest police station for help immediately!"] = "Ah, esqueça! {Sr.{Sra.|}}, por favor, tenha cuidado, tente atrasá-lo o máximo possível, irei imediatamente à delegacia de polícia mais próxima para obter ajuda!",
  ["Thank you so much! You are simply {{King of Loofahs|Queen of Loofahs}}. I'm going to cook a bowl of loofah soup to drink when I get home tonight."] = "Muito obrigado! Você é simplesmente {{Rei das Buchas | Rainha das Buchas}}. Vou preparar uma tigela de sopa de bucha para beber quando chegar em casa esta noite.",
  ["(Muttering) The loofahs aren't selling, {{this kind Mr.|this kind Ms.}}, can you help me? Please."] = "(Murmurando) As buchas não estão vendendo, {{esse gentil Sr.|essa gentil Sra.}}, você pode me ajudar? Por favor.",
  ["When he gets back, I'm going to give him a piece of my mind!"] = "Quando ele voltar, vou dizer-lhe o que penso!",
  ["Thank you, brave {Mr.{Ms.|}}."] = "Obrigado, corajoso {Sr.{Sra.|}}.",
  ["You know each other?"] = "Vocês se conhecem?",
  ["You are very concerned about {{PlayerName}}. Who exactly is {{him|her}}?"] = "Você está muito preocupado com {{PlayerName}}. Quem exatamente é {{ele|ela}}?",
  ["I should go. Help me pass this note to {{PlayerName}}. Entering the gray fog of history consumed too much spirituality. Let {{him|her}} have a good rest at Blackthorn tonight."] = "Eu deveria ir. Ajude-me a passar esta nota para {{PlayerName}}. Entrar na névoa cinzenta da história consumiu muito espiritualidade . Deixe {{ele | ela}} ter um bom descanso em Blackthorn esta noite.",
  ["<P_Heart> (startled) </> N-nothing. I was just thinking about something..."] = "<P_Heart> (assustado) </> N-nada. Eu estava pensando em uma coisa...",
  ["Please take a break from the hustle and bustle of this moment and come to my side."] = "Por favor, faça uma pausa na agitação deste momento e venha para o meu lado.",
  ["And it tries to ram the door every once in a while!"] = "E tenta bater na porta de vez em quando!",
  ["There have been at least seven factory machinery failure accidents in the last six months."] = "Houve pelo menos sete acidentes com falhas em máquinas de fábrica nos últimos seis meses.",
  ["Hey, have you heard of the 'Golden Dream'? They say the sails of that ship turn into crystal under the moonlight!"] = "Ei, você já ouviu falar do 'Sonho Dourado'? Dizem que as velas daquele navio se transformam em cristal sob o luar!",
  ["Ying—"] = "Sim—",
  ["Do me a favor, take it for a walk around the street, and help me see how everyone—especially those pickiest gourmets—reacts to it?"] = "Faça-me um favor, leve-o para passear pela rua e ajude-me a ver como todos - especialmente os gourmets mais exigentes - reagem a ele?",
  ["{Mr.{Ms.|}}, I know this is a bit presumptuous, but would you be willing to help me investigate this matter and catch that mysterious seller?"] = "{Sr.{Sra.|}}, eu sei que isso é um pouco presunçoso, mas você estaria disposto a me ajudar a investigar este assunto e pegar aquele vendedor misterioso?",
  ["The next day"] = "No dia seguinte",
  ["So straightforward? Aren't you afraid I'll photograph something I shouldn't?"] = "Tão simples? Você não tem medo que eu fotografe algo que não deveria?",
  ["Sorry {Mr.{Ms.|}}, it was me who brought you here and made you eat unclean food."] = "Desculpe {Sr.{Sra.|}}, fui eu quem trouxe você aqui e fez você comer comida impura.",
  ["{Mr.{Ms.|}}, follow me."] = "{Sr.{Sra.|}}, siga-me.",
  ["This {Mr.{Ms.|}}, can you help me hold my place in line? I've been waiting for hours and I really can't hold it anymore, I have to go to the restroom... We can dine together later!"] = "Este {Sr.{Sra.|}}, você pode me ajudar a manter meu lugar na fila? Estou esperando há horas e realmente não aguento mais, tenho que ir ao banheiro... Podemos jantar juntos mais tarde!",
  ["Don't worry, it's just a photo. This is a memento for myself, and also a gift of gratitude the crow wanted to give you."] = "Não se preocupe, é apenas uma foto. Esta é uma lembrança para mim e também um presente de gratidão que o corvo queria lhe dar.",
  ["Kingdom news? The Minister of the Interior's birthday today, does that count?"] = "Notícias do Reino? Aniversário do Ministro do Interior hoje, isso conta?",
  ["And for us, the best thing we can hope for every day is that someone like you is willing to reach into your pocket and throw us something, asking us to help carry luggage, lead a horse, or deliver a letter."] = "E para nós, a melhor coisa que podemos esperar todos os dias é que alguém como você esteja disposto a enfiar a mão no bolso e nos jogar alguma coisa, pedindo-nos para ajudar a carregar a bagagem, conduzir um cavalo ou entregar uma carta.",
  ["Yes. {Mr.{Ms.|}}, you are the kind of person who lives with money."] = "Sim. {Sr.{Sra.|}}, você é o tipo de pessoa que vive com dinheiro.",
  ["Nothing, I met a child who claimed to be the Minister of Finance earlier, he asked me for some money, is he also your subject?"] = "Nada, conheci antes uma criança que dizia ser Ministro das Finanças, ele me pediu algum dinheiro, ele também é seu súdito?",
  ["Perhaps I can help you fetch the hat?"] = "Talvez eu possa ajudá-lo a buscar o chapéu?",
  ["Madam, you look very troubled."] = "Senhora, você parece muito perturbada.",
  ["<P_Heart> (Although the effect was achieved, why does it feel different from what I expected.) </>"] = "<P_Heart> (Embora o efeito tenha sido alcançado, por que parece diferente do que eu esperava.) </>",
  ["<P_Heart> (sincere) </> Would you like to sign up for a singing class? I know a teacher who teaches quite well."] = "<P_Heart> (sincero) </> Gostaria de se inscrever em uma aula de canto? Conheço um professor que ensina muito bem.",
  ["I was almost blown back by your high pitch when I ran to the door."] = "Quase fui surpreendido pelo seu tom agudo quando corri para a porta.",
  ["I don't dare. I've been sitting here for two hours, and my legs are weak."] = "Eu não me atrevo. Estou sentado aqui há duas horas e minhas pernas estão fracas.",
  ["What's wrong with you? Are you feeling unwell?"] = "O que você tem? Você não está se sentindo bem?",
  ["Everything is fine, dear! Why don't you take Walter over there to buy a newspaper? Alright, go on!"] = "Está tudo bem, querido! Por que você não leva Walter até lá para comprar um jornal? Tudo bem, vá em frente!",
  ["Hell, what are you talking about? He made a huge fortune in Intis, and I still have that letter with me!"] = "Inferno, do que você está falando? Ele fez uma fortuna enorme no Intis e ainda tenho aquela carta comigo!",
  ["Thank you for your help, {Mr.{Ms.|}}. This is a small token of meeting, looking forward to our next meeting."] = "Obrigado pela sua ajuda, {Sr.{Sra.|}}. Este é um pequeno símbolo de reunião, aguardando ansiosamente nossa próxima reunião.",
  ["Hmm, they also have very easily identifiable catchphrases, praising each other as <P_Yellow> humorous, witty, and funny </> ."] = "Hmm, eles também têm bordões facilmente identificáveis, elogiando uns aos outros como <P_Yellow> bem-humorados, espirituosos e engraçados </> .",
  ["That doesn't sound like a difficult thing."] = "Isso não parece algo difícil.",
  ["Hmm... that kind of alternative humor can also be considered a form of the art of speech."] = "Hmm... esse tipo de humor alternativo também pode ser considerado uma forma de arte da fala.",
  ["At the same time, this also allows me to learn more about the art of human speech."] = "Ao mesmo tempo, isto também me permite aprender mais sobre a arte da fala humana.",
  ["A talking Cat... are you a true Spectator?"] = "Um gato falante... você é um verdadeiro espectador?",
  ["Hello, {Mr.{Ms.|}}."] = "Olá, {Sr.{Sra.|}}.",
  ["Ha! No wonder the quality inspection company representative calls the safety budget \"feeding the machines vegetarian food\"... Maybe they'll propose feeding the boilers pies to reduce accidents next!"] = "Ha! Não admira que o representante da empresa de inspeção de qualidade chame o orçamento de segurança de \"alimentar as máquinas com comida vegetariana\"... Talvez a seguir proponham alimentar as caldeiras com tortas para reduzir acidentes!",
  ["<P_Heart> (reading aloud) </> Honest people who attended the charity auction revealed that the quality inspection company boss's pocket watch is enough to trade for twenty safety valves!"] = "<P_Heart> (lendo em voz alta) </> Pessoas honestas que participaram do leilão beneficente revelaram que o relógio de bolso da empresa de inspeção de qualidade chefe é suficiente para ser trocado por vinte válvulas de segurança!",
  ["<P_Heart> (Lowers voice) </> Some councilors suggest entrusting this matter to the Church of the Evernight Goddess for investigation... You know, they are very good at dealing with things like Evil Spirit hauntings."] = "<P_Heart> (Abaixa a voz) </> Alguns conselheiros sugerem confiar este assunto à Igreja da Deusa da Noite Eterna para investigação... Você sabe, eles são muito bons em lidar com coisas como assombrações de Espíritos Malignos.",
  ["You know, all the boilers involved passed the \"Premium Grade\" inspection by the quality inspection company at the beginning of the year."] = "Você sabe, todas as caldeiras envolvidas passaram na inspeção de “Grau Premium” da empresa de inspeção de qualidade no início do ano.",
  ["But every investigation report says \"failure cannot be reproduced.\" Don't you think this is suspicious?"] = "Mas todos os relatórios de investigação dizem que “o fracasso não pode ser reproduzido”. Você não acha que isso é suspeito?",
  ["That's still better than being trapped on the dock for a lifetime! At least those sailors and pirates have seen the true legends of the sea!"] = "Isso ainda é melhor do que ficar preso no cais pelo resto da vida! Pelo menos aqueles marinheiros e piratas viram as verdadeiras lendas do mar!",
  ["But the sea is dangerous... It's said that the most terrifying things on the sea aren't even the storms, but those unseen things."] = "Mas o mar é perigoso... Dizem que as coisas mais terríveis no mar nem são as tempestades, mas sim aquelas coisas invisíveis.",
  ["Where did you get it? How could their route map fall into your hands? Is it real?"] = "Onde você conseguiu isso? Como o mapa de rotas deles poderia cair em suas mãos? É real?",
  ["Look! I got their route map from three years ago! It is said that the 'Golden Dream' buried immeasurable treasure on a mysterious island!"] = "Olhar! Recebi o mapa de rotas deles há três anos! Diz-se que o 'Sonho Dourado' enterrou um tesouro imensurável em uma ilha misteriosa!",
  ["But Old Tom said he saw it with his own eyes! When the 'Golden Dream' passes by, even the surging Sea Wave will stop!"] = "Mas o Velho Tom disse que viu com os próprios olhos! Quando o 'Sonho Dourado' passar, até mesmo a onda do mar irá parar!",
  ["That's quite amazing."] = "Isso é incrível.",
  ["Haha, tastes great, right? It's my family's secret recipe; you won't find such fragrant craft beer even in Intis."] = "Haha, tem um gosto ótimo, certo? É a receita secreta da minha família; você não encontrará cerveja artesanal tão perfumada nem no Intis.",
  ["Let me help you find them together."] = "Deixe-me ajudá-lo a encontrá-los juntos.",
  ["I suffer from intermittent amnesia, and every day I wake up, I forget what happened yesterday."] = "Sofro de amnésia intermitente e todos os dias que acordo esqueço o que aconteceu ontem.",
  ["Honey, I also hope he will be waiting for us at the door when we get home."] = "Querida, também espero que ele esteja nos esperando na porta quando chegarmos em casa.",
  ["Mom, will Dad be on the next train?"] = "Mãe, o pai estará no próximo trem?",
  ["It will, it will be taller than me, taller than you, taller than all of us!"] = "Será, será mais alto que eu, mais alto que você, mais alto que todos nós!",
  ["A little deeper, so the roots can take hold firmly!"] = "Um pouco mais fundo, para que as raízes possam firmar-se com firmeza!",
  ["This tree... I don't remember... You, you look very much like my son..."] = "Essa árvore... não me lembro... Você, você se parece muito com meu filho...",
  ["Can I join the Dragon Hunter Gang? I want to hunt dragons too! Where is Boss Kevin? I want to find him for an autograph!"] = "Posso me juntar à gangue Dragon Hunter? Eu também quero caçar dragões! Onde está Chefe Kevin? Quero encontrá-lo para um autógrafo!",
  ["Evernight Goddess, who is more noble than the stars and more eternal than eternity"] = "Deusa da Meia Noite, que é mais nobre que as estrelas e mais eterna que a eternidade",
  ["……Are you sweeping the floor or fighting? Use less force, keep your core steady……"] = "......Você está varrendo o chão ou lutando? Use menos força, mantenha seu núcleo estável......",
  ["Come, try it."] = "Venha, experimente.",
  ["You, you are even more meddlesome than this old bag of bones."] = "Você é ainda mais intrometido do que esse velho saco de ossos.",
  ["I just didn't expect that someone would be willing to stand up for a sweeper."] = "Só não esperava que alguém estivesse disposto a defender um varredor.",
  ["If they are unreasonable, I also know a thing or two about fighting."] = "Se eles não forem razoáveis, também sei algumas coisas sobre luta.",
  ["Young man, good skills. But... actually, you didn't have to intervene."] = "Jovem, boas habilidades. Mas... na verdade, você não precisou intervir.",
  ["Beautiful, beautiful! It's even redder than my bowtie!"] = "Linda, linda! É ainda mais vermelho que minha gravata borboleta!",
  ["I'm wearing new lipstick today, does it look good?"] = "Estou usando batom novo hoje, parece bom?",
  ["Sounds pretty good."] = "Parece muito bom.",
  ["What a sturdy chest! It seems it can't be pried open directly."] = "Que peito robusto! Parece que não pode ser aberto diretamente.",
  ["Stop making excuses. Tell Mr. Yate that this year I will grow the biggest and sweetest pumpkins, even sweeter than his grapes!"] = "Pare de dar desculpas. Diga ao Sr. Yate que este ano cultivarei as abóboras maiores e mais doces, ainda mais doces que as uvas dele!",
  ["But Professor, only church scriptures contain more records regarding the War of the Four Emperors. Perhaps finding the common truth within these documents is more likely..."] = "Mas professor, apenas as escrituras da igreja contêm mais registros sobre a Guerra dos Quatro Imperadores. Talvez seja mais provável encontrar a verdade comum nestes documentos...",
  ["Susie's identity allows her to avoid many troubles. When we are at a loss for what to do, Susie just says—'I don't know, after all, I am just a dog.'"] = "A identidade de Susie permite que ela evite muitos problemas. Quando não sabemos o que fazer, Susie apenas diz: 'Não sei, afinal, sou apenas um cachorro.'",
  ["Miss Audrey, do you have a title? If I wish to pray to you for help, what should I chant?"] = "Senhorita Audrey, você tem um título? Se eu quiser pedir ajuda a você, o que devo cantar?",
  ["Damn it, let's just break up if it's going to be like this!"] = "Droga, vamos terminar se vai ser assim!",
  ["You reach out to probe, but the treasure chest doesn't budge—it's locked."] = "Você estende a mão para sondar, mas o baú do tesouro não se move – está trancado.",
  ["If you want to open this chest, you have to play a game with me."] = "Se você quiser abrir este baú, terá que jogar comigo.",
  ["Interesting, were you trying to bypass me just now? Too bad, you've already been \"remembered\" by me."] = "Interessante, você estava tentando me ignorar agora há pouco? Que pena, você já foi “lembrado” por mim.",
  ["Wait, {Mr.{Ms.|}}."] = "Espere, {Sr.{Sra.|}}.",
  ["Spectator pathway Beyonders can not only perform Psychotherapy, but also use Mind Control to drive Beyonders to collapse."] = "O espectador Caminho Beyonders pode não apenas realizar psicoterapia, mas também usar o controle mental para levar Beyonders ao colapso.",
  ["This is not Invisibility in the traditional sense, but 'Psychological Invisibility'—when cognition is guided by suggestion, reality also slips out of the field of vision."] = "Isto não é Invisibilidade no sentido tradicional, mas sim “Invisibilidade Psicológica” – quando a cognição é guiada pela sugestão, a realidade também escapa do campo de visão.",
  ["What? Miss Susie is using Invisibility?"] = "O que? Senhorita Susie está usando Invisibilidade?",
  ["For example, you cannot see Susie right now, but she is indeed lying at your feet enjoying a nap."] = "Por exemplo, você não pode ver Susie agora, mas ela realmente está deitada a seus pés, tirando uma soneca.",
  ["The Sequence name \"Spectator\" might make people mistakenly think this is a Pathway only good at observation and support. But in reality, it is also a form of disguise—a disguise that makes people underestimate you even more."] = "O nome Sequência \"Espectador\" pode fazer as pessoas pensarem erroneamente que este é um Caminho bom apenas para observação e suporte. Mas, na realidade, é também uma forma de disfarce – um disfarce que faz com que as pessoas o subestimem ainda mais.",
  ["Miss Audrey, is your identity in the real world that of a psychiatrist?"] = "Senhorita Audrey, a sua identidade no mundo real é a de um psiquiatra?",
  ["I cannot give you a sum of money directly every time, but I can teach you how to invest. Emperor Roselle once said, 'It is better to teach a man how to fish than to give him a fish!'"] = "Não posso lhe dar uma quantia em dinheiro diretamente todas as vezes, mas posso lhe ensinar como investir. O Imperador Roselle disse uma vez: 'É melhor ensinar um homem a pescar do que dar-lhe um peixe!'",
  ["In any case! If you are short on money in the future, you can come to me."] = "Em todo o caso! Se você tiver pouco dinheiro no futuro, pode vir até mim.",
  ["Miss Audrey, thank you for the money you gave me earlier."] = "Senhorita Audrey, obrigado pelo dinheiro que me deu antes.",
  ["Miss Audrey, why can Susie speak? Is she... a magical creature?"] = "Senhorita Audrey, por que Susie consegue falar? Ela é... uma criatura mágica?",
  ["Understood. Thank you; I have learned some more Beyonder knowledge."] = "Entendido. Obrigado; Aprendi mais alguns Beyonder conhecimentos.",
  ["In the Extraordinary World, chanting an unfamiliar honorific name is very likely to summon unknown dangers. Except for the honorific names of true Gods and your companions in the Tarot Club, you must not chant other honorific names."] = "No Mundo Extraordinário, cantar um nome honorífico desconhecido provavelmente evocará perigos desconhecidos. Exceto pelos nomes honoríficos de Deuses verdadeiros e seus companheiros no Clube do Tarô , você não deve cantar outros nomes honoríficos.",
  ["Haha, I'd love to meet this gentleman if I have the chance!"] = "Haha, adoraria conhecer esse senhor se tiver oportunidade!",
  ["It was an instructor named Azik. We were very close. It's been so long since we last spoke; I wonder how that fellow is doing."] = "Era um instrutor chamado Azik. Estávamos muito próximos. Já faz muito tempo desde a última vez que nos falamos; Eu me pergunto como esse sujeito está.",
  ["You arrived late; that was several years ago."] = "Você chegou atrasado; isso foi há vários anos.",
  ["Oh? Was there an opponent who matched the Professor's level?"] = "Oh? Houve um adversário que correspondesse ao nível do Professor?",
  ["A long time ago, there was a fellow who would always argue with me until his face turned red... That is truly a distant memory."] = "Há muito tempo atrás, havia um sujeito que sempre discutia comigo até ficar com o rosto vermelho... Essa é realmente uma lembrança distante.",
  ["Professor Cohen is very rigorous academically, and I am very happy to discuss my ideas with him."] = "O professor Cohen é muito rigoroso academicamente e fico muito feliz em discutir minhas ideias com ele.",
  ["Debate? Haha, it's just an exchange of research between my students and me; it doesn't qualify as a debate."] = "Debate? Haha, é apenas uma troca de pesquisas entre meus alunos e eu; não se qualifica como um debate.",
  ["Hello, young man. I've seen you here for a while; would you like to join the discussion?"] = "Olá, jovem. Já faz um tempo que vejo você aqui; você gostaria de participar da discussão?",
  ["<P_Heart>(What are they discussing?)</>"] = "<P_Heart> (O que eles estão discutindo?) </>",
  ["<P_Heart> (If I were a Beyonder too, I wouldn't be this panicked...) </>"] = "<P_Heart> (Se eu fosse um Beyonder também, não entraria em pânico...) </>",
  ["Kind {{Mr.|Ms.}}, if you like my dance, please go to the meat stall in front and support my sister Mary Jane's business."] = "Gentil {{Sr.|Sra.}}, se você gosta da minha dança, por favor vá até a barraca de carne na frente e apoie os negócios da minha irmã Mary Jane.",
  ["{{Mr.|Ms.}}! It's you! What drink would you like today?"] = "{{Sr.|Sra.}}! É você! Que bebida você gostaria hoje?",
  ["That's great! Thank you! My house is easy to find, it's the cottage closest to the lakeside!"] = "Isso é ótimo! Obrigado! Minha casa é fácil de encontrar, é a casa mais próxima da beira do lago!",
  ["Perhaps I could help you fetch your hat?"] = "Talvez eu possa ajudá-lo a pegar seu chapéu?",
  ["I wait here every day, wanting to welcome him looking my best, but I forgot my hat at home today."] = "Espero aqui todos os dias, querendo recebê-lo com a melhor aparência, mas hoje esqueci meu chapéu em casa.",
  ["Ma'am, you look very troubled."] = "Senhora, você parece muito perturbada.",
  ["Hello, {{Mr.|Ms.}}, we meet again."] = "Olá, {{Sr.|Sra.}}, nos encontramos novamente.",
  ["{{Young man, you have a sweet tongue. But talk is cheap. Once you get tired of looking at them, how about buying me a drink?|You have a sweet tongue. It's a pity that the lights here never wait for anyone. }}"] = "{{Jovem, você tem uma língua doce. Mas falar é barato. Quando você se cansar de olhar para eles, que tal me pagar uma bebida? Você tem uma língua doce. É uma pena que as luzes aqui nunca esperem por ninguém. }}",
  ["<P_Heart>(Although the effect was achieved, why does it feel different from what I expected?)</>"] = "<P_Heart> (Embora o efeito tenha sido alcançado, por que parece diferente do que eu esperava?) </>",
  ["<P_Heart>(Sincere)</> Do you want to sign up for a singing class? I know a teacher who teaches quite well."] = "<P_Heart> (Sincero) </> Quer se inscrever em uma aula de canto? Conheço um professor que ensina muito bem.",
  ["I was almost blown back by your high notes when I ran to the door."] = "Quase fiquei surpreso com suas notas altas quando corri para a porta.",
  ["<P_Heart> (He needs a little courage. A Bard's song will come in handy.) </>"] = "<P_Heart> (Ele precisa de um pouco de coragem. Uma canção de Bardo será útil.) </>",
  ["I don't dare. I've been sitting here for two hours, my legs are like jelly."] = "Eu não me atrevo. Estou sentado aqui há duas horas, minhas pernas estão parecendo gelatina.",
  ["<P_Heart>(Startled)</> No, nothing. I'm just thinking about something..."] = "<P_Heart> (Assustado) </> Não, nada. Só estou pensando em uma coisa...",
  ["What's wrong with you? Are you not feeling well?"] = "O que você tem? Você não está se sentindo bem?",
  ["Oh, I really can't do anything with you!"] = "Oh, eu realmente não posso fazer nada com você!",
  ["Sir, my head hurts so much, and I can't even open my eyes..."] = "Senhor, minha cabeça dói muito e não consigo nem abrir os olhos...",
  ["Third trip! This tin box is getting hotter and hotter! It's not going to explode, is it!"] = "Terceira viagem! Esta caixa de lata está ficando cada vez mais quente! Não vai explodir, vai!",
  ["For more styles, you can go to the \"Rain Halfway\" shop on the street to pick them out!"] = "Para mais estilos, você pode ir até a loja \"Rain Halfway\" na rua para escolhê-los!",
  ["Meow-woo..."] = "Miau-woo...",
  ["Last time after praying to the Lord of the Washroom, a policeman {{Mr.|Ms.}} descended from the sky and helped us solve the diarrhea problem. If we pray again, could it resurrect 'Caramel Bomb'?"] = "Da última vez, depois de orar ao Senhor do Banheiro, um policial {{Sr.|Sra.}} desceu do céu e nos ajudou a resolver o problema da diarreia. Se orarmos novamente, será que isso poderia ressuscitar a 'Bomba de Caramelo'?",
  ["Aston, I believe you understand that the church has its own stance. It is difficult to strip that away..."] = "Aston, acredito que você entende que a igreja tem sua própria postura. É difícil tirar isso...",
  ["My first successful investment was in the stock of a bicycle company. I didn't have enough money to buy the stock at the time, but my father taught me an investment technique."] = "Meu primeiro investimento bem-sucedido foi em ações de uma empresa de bicicletas. Eu não tinha dinheiro suficiente para comprar as ações na época, mas meu pai me ensinou uma técnica de investimento.",
  ["My honorific name is—The Holy Spirit who sees all, the Blessed of the Yellow and Black King, the traveler of dreams and minds."] = "Meu nome honorífico é – O Espírito Santo que tudo vê, o Abençoado do Rei Amarelo e Preto, o viajante dos sonhos e das mentes.",
  ["{{Mr.|Ms.}}, would you like to buy some flowers?"] = "{{Sr.|Sra.}}, você gostaria de comprar algumas flores?",
  ["Sorry, {{Mr.|Ms.}}. I need to complete the preparations for setting sail as soon as possible, you can find my first mate..."] = "Desculpe, {{Sr.|Sra.}}. Preciso concluir os preparativos para zarpar o mais rápido possível, você pode encontrar meu primeiro imediato...",
  ["You know what I'm talking about, {{Mr.|Ms.}}. Use your meteorological instruments or something else to let our captain know that we shouldn't set sail today!"] = "Você sabe do que estou falando, {{Sr.|Sra.}}. Use seus instrumentos meteorológicos ou qualquer outra coisa para avisar nosso capitão que não devemos zarpar hoje!",
  ["It's like this, when I went on patrol this morning, I found that our kingdom was blocked. I tried to find a loophole, but I still couldn't return to the base."] = "É assim, quando saí em patrulha esta manhã, descobri que nosso reino estava bloqueado. Tentei encontrar uma brecha, mas ainda não consegui voltar à base.",
  ["Please step away from the noise of the moment and come to my side."] = "Por favor, afaste-se do barulho do momento e venha para o meu lado.",
  ["The appointed moment has arrived, my listener, and also the witness to this history."] = "Chegou o momento marcado, meu ouvinte, e também a testemunha desta história.",
  ["Good day, {Mr.{Ms.|}}. I am Jacob, a city guide certified by the City Hall. I can plan the most efficient tour route for you and answer most of your questions about this city."] = "Bom dia, {Sr.{Sra.|}}. Sou Jacob, guia da cidade certificado pela Prefeitura. Posso planejar a rota turística mais eficiente para você e responder a maioria das suas perguntas sobre esta cidade.",
  ["{Mr.{Ms.|}}, hello. Which station would you like to go to?"] = "{Sr.{Sra.|}}, olá. Para qual estação você gostaria de ir?",
  ["Yes, this {Mr.{Ms.|}}. I am about to return to Backlund with the young master..."] = "Sim, este {Sr.{Sra.|}}. Estou prestes a voltar para Backlund com o jovem mestre...",
  ["Actually, only True Gods can use three-part honorific names. My honorific name and those of other Tarot Club members borrow the True God status of Mr. Fool."] = "Na verdade, apenas os Deuses Verdadeiros podem usar nomes honoríficos de três partes. Meu nome honorífico e os de outros Clube do Tarô membros tomam emprestado o status de Deus Verdadeiro do Sr.",
  ["{Mr.{Ms.|}}, I used to be a Magician, skilled at escaping from cages in front of everyone's eyes."] = "{Sr.{Sra.|}}, eu costumava ser um mágico, hábil em escapar de jaulas na frente dos olhos de todos.",
  ["{Mr.{Ms.|}}, is there anything I can help you with?"] = "{Sr.{Sra.|}}, há algo em que eu possa ajudá-lo?",
  ["{Mr.{Ms.|}}, would you like to experience our municipal convenience project this month? It's free to try during the promotional period; after that, you only need to insert 1 penny into the 'Offering Box' to unlock one. Shall I introduce these three models to you?"] = "{Sr.{Sra.|}}, gostaria de experimentar nosso projeto de conveniência municipal este mês? A avaliação é gratuita durante o período promocional; depois disso, você só precisa inserir 1 centavo na 'Caixa de Oferendas' para desbloquear uma. Devo apresentar esses três modelos para vocês?",
  ["Because I want to become famous, {{Mr.|Ms.}}. I'm waiting for a carriage from Backlund filled with big shots! I'm waiting for them to look at me!"] = "Porque eu quero me tornar famoso, {{Sr.|Sra.}}. Estou esperando uma carruagem de Backlund cheia de figurões! Estou esperando que eles olhem para mim!",
  ["Subjects, this situation is very urgent, and I need everyone's help. Minister of Military Intelligence, please explain the situation first."] = "Sujeitos, essa situação é muito urgente, e preciso da ajuda de todos. Ministro da Inteligência Militar, explique primeiro a situação.",
  ["Thank you so much, {{Mr.|Ms.}}. The members of the Tingen Fashion Association are truly the most difficult guests to host on this street!"] = "Muito obrigado, {{Sr.|Sra.}}. Os membros da Tingen Fashion Association são realmente os convidados mais difíceis de receber nesta rua!",
  ["I think this {{Mr.|Ms.}}'s sense of style isn't bad. If you are considering joining the Tingen Fashion Association..."] = "Eu acho que o senso de estilo desse {{Sr.|Sra.}} não é ruim. Se você está pensando em ingressar na Tingen Fashion Association...",
  ["{{Mr.|Ms.}}, I would love to introduce our association to you..."] = "{{Sr.|Sra.}}, eu adoraria apresentar nossa associação a você...",
  ["{{Mr.|Ms.}}, please rest assured, my uncle's medical skills are not bad either. He is in the consultation room."] = "{{Sr.|Sra.}}, por favor, fique tranquilo, as habilidades médicas do meu tio também não são ruins. Ele está na sala de consulta.",
  ["{{Mr.|Ms.}}, please rest assured, my grandmother can't remember the location of the medicine cabinet. If there is medicine you need to buy, please tell me."] = "{{Sr.|Sra.}}, por favor, fique tranquilo, minha avó não consegue se lembrar da localização do armário de remédios. Se houver algum remédio que você precise comprar, por favor me avise.",
  ["{{PlayerName}}{{Mr.|Ms.}} right, I have recorded it for you here, please sit on the chair opposite and wait."] = "{{PlayerName}}{{Sr.|Sra.}} certo, gravei para você aqui, por favor, sente-se na cadeira em frente e espere.",
  ["Oh... hm? Oh my, my ears are a bit dull and I didn't hear clearly, {{Young man|Young lady}}, could you say it again?"] = "Ah... hum? Nossa, meus ouvidos estão um pouco embotados e eu não ouvi claramente, {{Jovem|Mocinha}}, você poderia dizer de novo?",
  ["Ah, alright, I'll register you now... {{Young man|Young lady}}, what is your name? Where are you feeling unwell?"] = "Ah, tudo bem, vou registrar você agora... {{Jovem|Mocinha}}, qual é o seu nome? Onde você está se sentindo mal?",
  ["{{Young man|Young lady}}, are you here for a medical consultation or to pick up medicine?"] = "{{Jovem|Mocinha}}, você está aqui para uma consulta médica ou para comprar remédios?",
  ["It's you! Kind {{Mr.|Ms.}}"] = "É você! Gentil {{Sr.|Sra.}}",
  ["{{Mr.|Ms.}}, come and see the latest masterpiece of the God of Steam and Machinery Church—'Walker'!"] = "{{Sr.|Sra.}}, venha ver a mais recente obra-prima da Igreja do Deus do Vapor e das Máquinas - 'Walker'!",
  ["None of them feel quite right..."] = "Nenhum deles parece certo...",
  ["I'm counting on you, I... have no strength left..."] = "Conto com você, eu... não tenho mais forças...",
  ["Your spirituality is truly sharp, to be able to find me hiding. \n Why don't we play a game of hide-and-seek? Find all the treasure chests nearby, and you can open my treasure."] = "Seu espiritualidade é realmente afiado, para poder me encontrar escondido. \n Por que não brincamos de esconde-esconde? Encontre todos os baús de tesouro próximos e você poderá abrir meu tesouro.",
  ["Hmph, are you sent by the neighbors to steal pumpkins! It won't be that easy to beat me in the Harvest Festival!"] = "Hmph, você foi enviado pelos vizinhos para roubar abóboras! Não será tão fácil me vencer no Festival da Colheita!",
  ["And, it tries to crash through the door every once in a while!"] = "E tenta arrombar a porta de vez em quando!",
  ["As for why she can speak, it stems from... a small mistake, a small error that all dog owners make: forgetting that their dog can open doors."] = "Quanto ao motivo pelo qual ela consegue falar, é decorrente de... um pequeno erro, um pequeno erro que todos os donos de cães cometem: esquecer que seu cachorro pode abrir portas.",
  ["A three-line honorific name is not just a name; it is closer to a gaze of divinity, a spell of summoning."] = "Um nome honorífico de três linhas não é apenas um nome; está mais próximo de um olhar de divindade, de um feitiço de convocação.",
  ["It seems this {{Mr.|Ms.}} has been listening to our discussion for a long time. Are you also a loyal reader of Miss Fors?"] = "Parece que este {{Sr.|Sra.}} está ouvindo nossa discussão há muito tempo. Você também é um leitor fiel de Miss Fors?",
  ["Hello, {{Mr.|Ms.}}, the Very Fun Hotel welcomes you!"] = "Olá, {{Sr.|Sra.}}, o Very Fun Hotel lhe dá as boas-vindas!",
  ["{{Mr.|Ms.}}, you don't look like a rich person. I'll warn you in advance, the price of a glass of wine here might very well leave you without a single piece of clothing!"] = "{{Sr.|Sra.}}, você não parece uma pessoa rica. Já vou avisando, o preço de uma taça de vinho aqui pode muito bem te deixar sem uma única peça de roupa!",
  ["Marketing, it's all marketing, {{Mr.|Ms.}}, understand? Only in this way will it attract those dukes and ladies who haven't seen much of the world to come and buy wine."] = "Marketing, é tudo marketing, {{Sr.|Sra.}}, entendeu? Só assim atrairá aqueles duques e senhoras que não conheceram muito o mundo para virem comprar vinho.",
  ["Sorry, {{Mr.|Ms.}}, I'm just so happy!"] = "Desculpe, {{Sr.|Sra.}}, estou muito feliz!",
  ["{{Mr.|Ms.}}, would you like to buy an umbrella?"] = "{{Sr.|Sra.}}, você gostaria de comprar um guarda-chuva?",
  ["{{Mr.|Ms.}}, it's best to leave here before the next train arrives—the people getting off will squeeze you like sardines in a can!"] = "{{Sr.|Sra.}}, é melhor sair daqui antes que o próximo trem chegue—as pessoas que descem vão espremer você como sardinha em lata!",
  ["Don't be shy, {{Mr.|Ms.}}. There are many people like you who don't have enough money for a ticket."] = "Não seja tímido, {{Sr.|Sra.}}. Há muitas pessoas como você que não têm dinheiro suficiente para comprar uma passagem.",
  ["Hello, {{Mr.|Ms.}}! Would you like to buy a ticket?"] = "Olá, {{Sr.|Sra.}}! Gostaria de comprar um ingresso?",
  ["Welcome to Tingen, {{Mr.|Ms.}}! Would you like to take a carriage? It can reach anywhere in Tingen, and we even provide a free guided tour!"] = "Bem-vindo a Tingen, {{Sr.|Sra.}}! Você gostaria de pegar uma carruagem? Pode chegar a qualquer lugar em Tingen, e ainda oferecemos uma visita guiada gratuita!",
  ["{{Mr.|Ms.}}, the Tingen Morning Post for one linar, get a copy!"] = "{{Sr.|Sra.}}, o Tingen Morning Post para um linar, pegue uma cópia!",
  ["Everything is fine, dear! Why don't you take Walter over there to buy a newspaper? Alright, go on now!"] = "Está tudo bem, querido! Por que você não leva Walter até lá para comprar um jornal? Tudo bem, vá agora!",
  ["Hell, what are you talking about? He made a huge fortune in Intis; I still carry that letter with me!"] = "Inferno, do que você está falando? Ele fez uma enorme fortuna em Intis; Ainda carrego essa carta comigo!",
  ["Hello, {{Mr.|Ms.}}, I see the light of thirst for knowledge shining on your face!"] = "Olá, {{Sr.|Sra.}}, vejo a luz da sede de conhecimento brilhando em seu rosto!",
  ["{{This handsome gentleman, you heard wrong.|This noble lady, you heard wrong.}}"] = "{{Este belo cavalheiro, você ouviu errado. | Esta nobre senhora, você ouviu errado.}}",
  ["{{Mr.|Ms.}}, look at what it's called? It's called Cat!"] = "{{Sr.|Sra.}}, olha como se chama? Chama-se Gato!",
  ["Thank you for your help, {{Mr.|Ms.}}. This is a small token of appreciation. I look forward to our next meeting."] = "Obrigado pela sua ajuda, {{Sr.|Sra.}}. Este é um pequeno sinal de agradecimento. Aguardo com expectativa o nosso próximo encontro.",
  ["Hmm, they also have very easily identifiable catchphrases, praising each other as <P_Yellow> humorous, witty, and funny </>."] = "Hmm, eles também têm bordões facilmente identificáveis, elogiando uns aos outros como <P_Yellow> bem-humorados, espirituosos e engraçados </> .",
  ["That doesn't sound like a difficult task."] = "Isso não parece uma tarefa difícil.",
  ["Hmm... that kind of alternative humor can also be considered a form of the art of conversation."] = "Hmm... esse tipo de humor alternativo também pode ser considerado uma forma de arte da conversação.",
  ["At the same time, this allows me to learn more about the art of human conversation."] = "Ao mesmo tempo, isto me permite aprender mais sobre a arte da conversação humana.",
  ["I would like to ask you, in the realm of human language, can that conversation just now be considered interesting?"] = "Eu gostaria de perguntar a você, no âmbito da linguagem humana, essa conversa agora pode ser considerada interessante?",
  ["You may call me 'Poirot'."] = "Você pode me chamar de “Poirot”.",
  ["Hello, {{Mr.|Ms.}}."] = "Olá, {{Sr.|Sra.}}.",
  ["I think I'll take another look."] = "Acho que vou dar outra olhada.",
  ["That is not important at all."] = "Isso não é nada importante.",
  ["Thank you, {{Mr.|Ms.}}. The medical oath doesn't say 'count the coins before counting the pulse.' Regardless, I will uphold the ethics of a doctor to the very end."] = "Obrigado, {{Sr.|Sra.}}. O juramento médico não diz “conte as moedas antes de contar o pulso”. Independentemente disso, defenderei a ética de um médico até o fim.",
  ["Eh... wait, Lange, do you know them?"] = "Eh... espere, Lange, você os conhece?",
  ["Yes, they use names related to textiles. Only their leader has a decent name, called Hunter."] = "Sim, eles usam nomes relacionados a têxteis. Apenas o líder deles tem um nome decente, chamado Hunter.",
  ["Hat Gang... is that Iron Needle and Silk Thread and the others?"] = "Hat Gang... isso é Agulha de Ferro e Fio de Seda e os outros?",
  ["Report to the King, there is another force here called the \"Hat Gang,\" which is also composed of a group of orphans like us. Perhaps we can ask them for help!"] = "Reporte ao Rei, há outra força aqui chamada “Gangue do Chapéu”, que também é composta por um grupo de órfãos como nós. Talvez possamos pedir ajuda a eles!",
  ["The most urgent thing right now is to find a place for us to stay tonight. Minister of Foreign Affairs, you are familiar with this area of the Tingen market, do you have any good ideas?"] = "A coisa mais urgente agora é encontrar um lugar para ficarmos esta noite. Ministro das Relações Exteriores, o senhor conhece esta área do mercado de Tingen, tem alguma boa ideia?",
  ["{{Mr.|Ms.}}, over there, the Loen people have a lot of say. As long as you wear a formal suit, a top hat, a bow tie, and carry a walking stick, the people around you will be submissive to you."] = "{{Sr.|Sra.}}, ali, o pessoal de Loen tem muito a dizer. Contanto que você use um terno formal, cartola, gravata borboleta e carregue uma bengala, as pessoas ao seu redor serão submissas a você.",
  ["{{Mr.|Ms.}}, are you also waiting for the \"Generosity\"?"] = "{{Sr.|Sra.}}, você também está esperando pela “Generosidade”?",
  ["That's right! {{Mr.|Ms.}}, do you also understand the mystery of it?"] = "Isso mesmo! {{Sr.|Sra.}}, você também entende o mistério disso?",
  ["And your little... rabbit? Bear? Uh, duck? Anyway, no matter what it is, Grandma has fixed it for you, exactly the same as before."] = "E seu coelhinho? Urso? Uh, pato? De qualquer forma, não importa o que seja, a vovó consertou para você, exatamente como antes.",
  ["Hello, {{Mr.|Ms.}}. As you can see, I am researching a... magical bill regarding sewage treatment."] = "Olá, {{Sr.|Sra.}}. Como você pode ver, estou pesquisando um projeto de lei mágico sobre tratamento de esgoto.",
  ["Ha! No wonder the quality inspection company representative called the safety budget 'feeding the machines vegetarian food'... I'm afraid they'll propose feeding the boilers pies to reduce accidents next!"] = "Ha! Não é à toa que o representante da empresa de inspeção de qualidade chamou o orçamento de segurança de 'alimentar as máquinas com comida vegetariana'... Receio que a seguir eles proponham alimentar as caldeiras com tortas para reduzir acidentes!",
  ["<P_Heart> (Reads aloud) </> An honest man who attended the charity auction revealed that the quality inspection company boss's pocket watch is enough to trade for twenty sets of safety valves!"] = "<P_Heart> (Lê em voz alta) </> Um homem honesto que participou do leilão de caridade revelou que o relógio de bolso da empresa de inspeção de qualidade chefe é suficiente para ser trocado por vinte conjuntos de válvulas de segurança!",
  ["<P_Heart> (Lowering voice) </> Some councilors suggested entrusting this matter to the Church of the Evernight Goddess for investigation... You know, they are very good at dealing with things like evil spirits haunting places."] = "<P_Heart> (Voz baixa) </> Alguns conselheiros sugeriram confiar este assunto à Igreja da Deusa da Noite Eterna para investigação... Você sabe, eles são muito bons em lidar com coisas como espíritos malignos assombrando lugares.",
  ["Are you saying there is a hidden story behind this?"] = "Você está dizendo que há uma história oculta por trás disso?",
  ["You know, all the boilers involved passed the 'Premium Grade' inspection by the quality inspection company at the beginning of the year."] = "Você sabe, todas as caldeiras envolvidas passaram na inspeção de 'Grau Premium' da empresa de inspeção de qualidade no início do ano.",
  ["But every investigation report says 'unable to reproduce the fault.' Don't you think this is suspicious?"] = "Mas todos os relatórios de investigação dizem “incapaz de reproduzir a falha”. Você não acha que isso é suspeito?",
  ["The \"Tingen Honest Man\" says our safety regulations are like the fake beards in an opera house—they look good but are useless."] = "O \"Homem Honesto de Tingen\" diz que nossas normas de segurança são como as barbas falsas de um teatro de ópera: parecem boas, mas são inúteis.",
  ["There have been no fewer than seven factory machinery failure accidents in the last six months."] = "Houve nada menos que sete acidentes com falhas em máquinas de fábrica nos últimos seis meses.",
  ["I understand their feelings very well, and I envy them for still being able to find the mementos of important people."] = "Entendo muito bem os sentimentos deles e os invejo por ainda conseguirem encontrar lembranças de pessoas importantes.",
  ["Those who are alive often need something to commemorate those who have passed away."] = "Aqueles que estão vivos muitas vezes precisam de algo para comemorar aqueles que já faleceram.",
  ["As you can see, the ending is not perfect... so he entrusted me to use the girl's mementos and the wedding ring he prepared to make a brand-new ring, to forever commemorate his late lover."] = "Como você pode ver, o final não é perfeito... então ele me confiou para usar as lembranças da garota e a aliança que ele preparou para fazer um anel totalmente novo, para homenagear para sempre seu falecido amante.",
  ["It is the hair of his late fiancée. That brave girl died in the Feysac War, and my client has been searching for her for many years."] = "É o cabelo de sua falecida noiva. Aquela corajosa garota morreu na Guerra de Feysac, e meu cliente a procura há muitos anos.",
  ["They are all in a classical, gorgeous style, with gold, pearls, and diamonds forming bouquets, butterflies, and the Ouroboros representing eternity. They are very decent pieces of jewelry with a strong presence."] = "Eles são todos em um estilo clássico e lindo, com ouro, pérolas e diamantes formando buquês, borboletas e Ouroboros representando a eternidade. São peças de joalharia muito decentes e com uma presença forte.",
  ["That is precisely why the lady invested in many jewelers like Miss Alice."] = "Justamente por isso a senhora investiu em muitas joalherias como Miss Alice.",
  ["Only by becoming cheaper can it be bought by more people. As long as enough people buy it, we can define what is fashionable—that is worth much more than the raw materials."] = "Somente ficando mais barato poderá ser comprado por mais pessoas. Desde que um número suficiente de pessoas compre, poderemos definir o que está na moda – que vale muito mais do que as matérias-primas.",
  ["The piling up of wealth is outdated; it should stay safely in a vault. From now on, craftsmanship is the fashion, and Miss Alice has always had a sharp nose for this."] = "A acumulação de riqueza está ultrapassada; ele deve ficar em segurança em um cofre. De agora em diante o artesanato está na moda, e a dona Alice sempre teve faro para isso.",
  ["In the past, only the nobility could define excellent design, even if those were too cumbersome and monotonous—a manual piling up of large amounts of gold, pearls, and coral..."] = "No passado, apenas a nobreza poderia definir um design excelente, mesmo que fosse muito pesado e monótono – um empilhamento manual de grandes quantidades de ouro, pérolas e corais...",
  ["This always reminds me of the Moretti family—they were my neighbors back then. The eldest son of that family took the first government employee exam, and now, they have moved to Backlund."] = "Isso sempre me lembra a família Moretti – eles eram meus vizinhos naquela época. O filho mais velho daquela família fez o primeiro exame para funcionário público e agora mudou-se para Backlund.",
  ["It's a cozy place, but most of my neighbors from back then have moved away. It's a pity..."] = "É um lugar aconchegante, mas a maioria dos meus vizinhos daquela época se mudou. É uma pena...",
  ["How is it, how is it? How was the feedback on my new recipe?"] = "Como é, como é? Como foi o feedback sobre minha nova receita?",
  ["Sir, where are you going?"] = "Senhor, onde você está indo?",
  ["How many times lost? How many times won? No one remembers. You seemed to have fought until the end of the world, the edge of the universe."] = "Quantas vezes perdido? Quantas vezes ganhou? Ninguém se lembra. Você parecia ter lutado até o fim do mundo, o fim do universo.",
  ["The noisy card table went quiet for a moment, then became noisy again, and you threw the cards forward fiercely with the willpower you used to break free from the red cocoon."] = "A barulhenta mesa de jogo ficou em silêncio por um momento, depois tornou-se barulhenta novamente, e você jogou as cartas para frente com força com a força de vontade que usou para se libertar do casulo vermelho.",
  ["Let me handle this."] = "Deixe-me cuidar disso.",
  ["The card game was long, as long as the sadness pouring out of the man who had lost fifteen games in a row."] = "O jogo de cartas foi longo, tão longo quanto a tristeza que emanava do homem que havia perdido quinze partidas seguidas.",
  ["You sat down next to the little dog, and it looked at you in confusion, politely staying by your side. The two of you, quiet, stood in opposition to the noisy card table."] = "Você se sentou ao lado do cachorrinho, e ele te olhou confuso, permanecendo educadamente ao seu lado. Vocês dois, quietos, ficaram em oposição à barulhenta mesa de jogo.",
  ["Hey, you brat over there, be quiet while playing with the dog! I can't afford to lose anymore!"] = "Ei, seu pirralho aí, fique quieto enquanto brinca com o cachorro! Não posso mais me dar ao luxo de perder!",
  ["Don't mention looking after kids—hurry, hurry, I have to go home in five minutes, there's still time for one more round before then!"] = "Não fale em cuidar das crianças – rápido, rápido, tenho que ir para casa em cinco minutos, ainda dá tempo para mais uma rodada antes disso!",
  ["Another round? Or are you going back to look after the kids?"] = "Outra rodada? Ou você vai voltar para cuidar das crianças?",
  ["Dogs are born to bark... you lost, buddy, don't take your anger from looking after a baby out on the dog."] = "Cachorro nasce para latir... você perdeu, amigo, não leve a raiva de cuidar de um bebê para cima do cachorro.",
  ["Whimper—"] = "Choramingar-",
  ["Jimmy, {{Mr.|Ms.}}... Mom works as a maid during the day and has to go out to dance in very cold clothes at night. She said she would send me to be an apprentice when she saved enough money. But... but the police said Mom did something bad... is Mom a bad person?"] = "Jimmy, {{Sr.|Sra.}}... Mamãe trabalha como empregada doméstica durante o dia e tem que sair para dançar com roupas muito frias à noite. Ela disse que me enviaria para ser aprendiz quando economizasse dinheiro suficiente. Mas... mas a polícia disse que mamãe fez algo ruim... mamãe é uma pessoa má?",
  ["What's your name?"] = "Qual o seu nome?",
  ["Hey, I don't know where this ship is headed. But I think my opportunity has arrived... Do you want a painting, {{Mr.|Ms.}}?"] = "Ei, não sei para onde esse navio está indo. Mas acho que minha oportunidade chegou... Você quer uma pintura, {{Sr.|Sra.}}?",
  ["Shh... keep it down. {{Mr.|Ms.}}, do you want to buy a painting? The kind that makes you happy; it's not expensive."] = "Shh... fale baixo. {{Sr.|Sra.}}, você quer comprar uma pintura? Do tipo que te faz feliz; não é caro.",
  ["Hello, {{PlayerName}}{{Mr.|Ms.}}, happy to be of service."] = "Olá, {{PlayerName}}{{Sr.|Sra.}}, fico feliz em poder ajudar.",
  ["{{Mr.|Ms.}}, are you looking to rent a house?"] = "{{Sr.|Sra.}}, você quer alugar uma casa?",
  ["There are too many uncertain contents regarding the history of the Fourth Epoch. You should start your research from existing relics to eliminate uncertain factors."] = "Existem muitos conteúdos incertos sobre a história da Quarta Época. Você deve começar sua pesquisa a partir de relíquias existentes para eliminar fatores incertos.",
  ["On the day I concocted the potion, Susie opened the door and entered the laboratory, licking a portion of the Spectator potion. Fortunately, I had prepared two sets of materials at the time."] = "No dia em que preparei a poção, Susie abriu a porta e entrou no laboratório, lambendo uma porção da poção do Espectador. Felizmente, preparei dois conjuntos de materiais na época.",
  ["So your second line of the honorific name is 'Blessed of the Yellow and Black King'."] = "Portanto, sua segunda linha do nome honorífico é 'Abençoado do Rei Amarelo e Preto'.",
  ["That's still better than being stuck on the docks for a lifetime! At least those sailors and pirates have seen the true legends of the sea!"] = "Isso ainda é melhor do que ficar preso nas docas por toda a vida! Pelo menos aqueles marinheiros e piratas viram as verdadeiras lendas do mar!",
  ["But the sea is dangerous... It is said that the most terrifying things on the sea are not even the storms, but those unseen things."] = "Mas o mar é perigoso... Diz-se que as coisas mais terríveis no mar nem são as tempestades, mas sim aquelas coisas invisíveis.",
  ["Where did you get it? How could their route map fall into your hands? Is it true?"] = "Onde você conseguiu isso? Como o mapa de rotas deles poderia cair em suas mãos? É verdade?",
  ["Look! I got their route map from three years ago! It is said that the \"Golden Dream\" buried immeasurable treasure on a mysterious island!"] = "Olhar! Recebi o mapa de rotas deles há três anos! Diz-se que o “Sonho Dourado” enterrou um tesouro imensurável em uma ilha misteriosa!",
  ["But Old Tom said he saw it with his own eyes! When the Golden Dream passes by, even the surging sea waves will stand still!"] = "Mas o Velho Tom disse que viu com os próprios olhos! Quando o Sonho Dourado passar, até as ondas do mar ficarão paradas!",
  ["Why does it sound like a story made up by drunken sailors..."] = "Por que parece uma história inventada por marinheiros bêbados...",
  ["Exactly! This {{Mr.|Ms.}}, you must also want to board the magnificent and mysterious \"Golden Dream\"!"] = "Exatamente! Este {{Sr.|Sra.}}, você também deve querer embarcar no magnífico e misterioso “Sonho Dourado”!",
  ["That's quite magical."] = "Isso é muito mágico.",
  ["Admiral Iceberg's ship? I've heard some rumors."] = "O navio do almirante Iceberg? Eu ouvi alguns rumores.",
  ["{{Mr.|Ms.}}, want a newspaper?"] = "{{Sr.|Sra.}}, quer um jornal?",
  ["Quest finished"] = "Missão concluído",
  ["He's always obsessed with growing the sweetest pumpkins, haha, but his pumpkins are indeed very delicious!"] = "Ele está sempre obcecado em cultivar as abóboras mais doces, haha, mas as abóboras dele são realmente muito deliciosas!",
  ["Ah... you mean Mr. Rumber from the pumpkin field next door."] = "Ah... você quer dizer o Sr. Rumber do campo de abóboras ao lado.",
  ["Oh! If you like it, feel free to take some to drink when it's ready."] = "Oh! Se gostar, fique à vontade para levar um pouco para beber quando estiver pronto.",
  ["I plan to make these grapes into wine, just put them in a wooden barrel and wait for fermentation... This must be the best-tasting wine in the small town!"] = "Pretendo transformar essas uvas em vinho, basta colocá-las em um barril de madeira e aguardar a fermentação... Esse deve ser o vinho mais saboroso da pequena cidade!",
  ["Wh, what? He's going to use those grapes to make wine. Uh, well, that sounds pretty good... I like drinking!"] = "O que, o que? Ele vai usar essas uvas para fazer vinho. Uh, bem, isso parece muito bom... Eu gosto de beber!",
  ["Hmph, you're sensible. My pumpkins will definitely be the biggest and sweetest!"] = "Hmph, você é sensato. Minhas abóboras serão definitivamente as maiores e mais doces!",
  ["Where do you want to go? I'll definitely get you there on time!"] = "Para onde você quer ir? Com certeza chegarei lá na hora certa!",
  ["<P_Heart> (Let him end one of the relationships to benefit all three people.) </>"] = "<P_Heart> (Deixe-o terminar um dos relacionamentos para beneficiar todas as três pessoas.) </>",
  ["The streetlamp nearby suddenly broke recently, and I can't see anything when I get off work!"] = "O poste de luz próximo quebrou repentinamente recentemente e não consigo ver nada quando saio do trabalho!",
  ["The streetlamp is fixed! Now I can walk at night without worry."] = "O poste está consertado! Agora posso andar à noite sem me preocupar.",
  ["<P_Heart> (Sounds dangerous, I'll come take a look at night...) </>"] = "<P_Heart> (Parece perigoso, irei dar uma olhada à noite...) </>",
  ["They simply don't treat us like human beings! Ask? Asking is a waste of effort!"] = "Eles simplesmente não nos tratam como seres humanos! Perguntar? Perguntar é um desperdício de esforço!",
  ["<P_Heart> (Holding forehead) </> This lamp, I'll go ask about it again..."] = "<P_Heart> (Segurando a testa) </> Essa lâmpada, vou perguntar sobre ela de novo...",
  ["<P_Heart> (Helplessly) </> I've reported it to the higher-ups, but no one has dealt with it. Sigh, they don't care if we live or die."] = "<P_Heart> (Desamparado) </> Eu relatei isso aos superiores, mas ninguém lidou com isso. Suspiro, eles não se importam se vivemos ou morremos.",
  ["Really? But I don't think I misjudged it. Look at that cloud..."] = "Realmente? Mas não acho que julguei mal. Olha aquela nuvem...",
  ["I'll go to Lamud Castle to pacify Gina first, then borrow money from Gina to see Lily; she has always satisfied all my requests."] = "Irei primeiro ao Castelo Lamud para pacificar Gina, depois pedirei dinheiro emprestado a Gina para ver Lily; ela sempre atendeu a todos os meus pedidos.",
  ["No! If I leave Lily, I will lose my passion for life... If Gina leaves me, I will go crazy. I cannot give up either of them."] = "Não! Se eu deixar Lily, perderei minha paixão pela vida... Se Gina me deixar, ficarei louco. Não posso desistir de nenhum deles.",
  ["The results of you going to Golden Autumn Lake and Lamud Castle are not good in my divination. One should be devoted in love; it's better for you and those two young ladies."] = "Os resultados de você ir ao Golden Autumn Lake e ao Lamud Castle não são bons no meu adivinhação. Deve-se ser devotado em amor; é melhor para você e para aquelas duas jovens.",
  ["<P_Heart> (Better to advise him.) </>"] = "<P_Heart> (Melhor aconselhá-lo.) </>",
  ["Thank you for your revelation! Gina, I'm setting off to find you now. The quiet corners of the castle are meant for us to share our hearts!"] = "Obrigado pela sua revelação! Gina, vou procurar você agora. Os recantos tranquilos do castelo foram feitos para partilharmos os nossos corações!",
  ["<P_Heart> (Let him learn a lesson and stop his philandering.) </>"] = "<P_Heart> (Deixe-o aprender uma lição e parar de ser mulherengo.) </>",
  ["Please give me a revelation! Which place should I buy a Steam Train ticket for?"] = "Por favor, me dê uma revelação! Para qual lugar devo comprar uma passagem do Trem a Vapor?",
  ["Great Seer, <P_Yellow> Golden Autumn Lake </> and <P_Yellow> Lamud Castle </> both have people waiting for me, but my money only allows me to go to one place for the appointment."] = "Grande Vidente, <P_Yellow> Golden Autumn Lake </> e <P_Yellow> Lamud Castle </> ambos têm pessoas esperando por mim, mas meu dinheiro só me permite ir a um lugar para a consulta.",
  ["Are you... no, are you, are you a Seer!"] = "Você é... não, você é um Vidente!",
  ["Sigh, it looks like the children are going to be hungry again..."] = "Suspiro, parece que as crianças vão sentir fome de novo...",
  ["When the time comes, let Gehrman enter from that side, and then directly..."] = "Quando chegar a hora, deixe Gehrman entrar por aquele lado, e então diretamente...",
  ["Huh? You followed me too? I have to say, this is a great suggestion."] = "Huh? Você me seguiu também? Devo dizer que esta é uma ótima sugestão.",
  ["Then stand still. First of all, I declare—if you fall into someone's chimney again, remember to keep it a secret for me!"] = "Então fique parado. Em primeiro lugar, declaro: se você cair na chaminé de alguém novamente, lembre-se de manter isso em segredo para mim!",
  ["It's amazing! I knew it! Getting their approval makes me happier than winning any cooking competition. This is the real \"Gold Medal Certification\"!"] = "É incrível! Eu sabia! Obter a aprovação deles me deixa mais feliz do que vencer qualquer competição de culinária. Esta é a verdadeira “Certificação Medalha de Ouro”!",
  ["Buddy, got any \"squeakers\"?"] = "Amigo, tem algum \"guincho\"?",
  ["The silver-gilt tea set is carved with gorgeous emblems, making afternoon tea time even more elegant."] = "O serviço de chá em prata dourada é esculpido com lindos emblemas, tornando a hora do chá da tarde ainda mais elegante.",
  ["A beautifully carved wall-mounted vanity mirror. The mirror surface is clear enough to reflect every detail of your makeup."] = "Um espelho de maquilhagem de parede lindamente esculpido. A superfície do espelho é clara o suficiente para refletir todos os detalhes da sua maquiagem.",
  ["High-quality pure silver jewelry. The style is simple and ancient, highlighting the wearer's low-key yet sophisticated taste."] = "Joias de prata pura de alta qualidade. O estilo é simples e antigo, destacando o gosto discreto, porém sofisticado, do usuário.",
  ["A white porcelain plate with fine lace, warm to the touch. It is a decent choice for entertaining guests in an ordinary family."] = "Prato de porcelana branca com renda fina, quente ao toque. É uma escolha decente para receber convidados de uma família comum.",
  ["Cast in brass, decorated with simple yet elegant patterns. Suitable for daily lighting and decoration."] = "Fundido em latão, decorado com padrões simples mas elegantes. Adequado para iluminação e decoração diária.",
  ["Made by splicing and polishing white maple boards, the style is simple and suitable for daily desk storage."] = "Feito emendando e polindo placas de bordo branco, o estilo é simples e adequado para armazenamento diário em mesa.",
  ["Pressed from coarsely refined stone powder and meticulously carved to present a beautiful silhouette, it has a wide range of uses."] = "Prensado a partir de pó de pedra grosseiramente refinado e meticulosamente esculpido para apresentar uma bela silhueta, tem uma ampla gama de utilizações.",
  ["Ice cubes lock in the freshness and sweetness of the clam meat, and the slices are as crystal clear as snow and ice. Thanks for the gift from the depths of the sea."] = "Os cubos de gelo retêm o frescor e a doçura da carne de marisco, e as fatias são tão cristalinas quanto a neve e o gelo. Obrigado pelo presente das profundezas do mar.",
  ["Gold medal ham produced by a special royal supplier; the smoked flavor precipitates the deliciousness of time."] = "Presunto medalha de ouro produzido por fornecedor real especial; o sabor defumado precipita a delícia do tempo.",
  ["Mellow honey complemented by smoked pork, an excellent companion for breakfast. Bacon and eggs, my partner."] = "Mel suave complementado com carne de porco fumada, excelente companheiro ao pequeno-almoço. Bacon e ovos, meu parceiro.",
  ["After fresh milk is fermented, it forms a unique texture and leaves an alluring aroma, quite popular with cats and mice."] = "Após a fermentação do leite fresco, ele forma uma textura única e deixa um aroma sedutor, bastante apreciado por gatos e ratos.",
  ["Pressing refined sugar into cubes makes it a classic companion for Loenese black tea."] = "Prensar o açúcar refinado em cubos torna-o um companheiro clássico para o chá preto Loenese.",
  ["Classic cellared red wine, deep in color, smooth and full-bodied, worthy of being aged by time."] = "Vinho tinto clássico de adega, de cor profunda, macio e encorpado, digno de ser envelhecido pelo tempo.",
  ["Clear as the morning dew in a birch forest, the cold liquor burns with a flame-like stimulation."] = "Claro como o orvalho da manhã em uma floresta de bétulas, o licor frio queima com um estímulo semelhante ao de uma chama.",
  ["You can almost feel the cedar sprouting and breaking through the soil in your mouth, with a lingering, slightly bitter woody fragrance on your lips and tongue."] = "Você quase pode sentir o cedro brotando e rompendo o solo em sua boca, com uma fragrância amadeirada persistente e levemente amarga em seus lábios e língua.",
  ["Combining the slight bitterness of cocoa with the creaminess of milk, it's more like a dessert than an alcoholic beverage."] = "Combinando o leve amargor do cacau com a cremosidade do leite, parece mais uma sobremesa do que uma bebida alcoólica.",
  ["The clear, sweet liquid brings a tipsy feeling; every bubble dances lightly on the tip of the tongue."] = "O líquido límpido e doce traz uma sensação de embriaguez; cada bolha dança levemente na ponta da língua.",
  ["Happiness that can be bought for a few coins; a favorite for workers after a long day."] = "Felicidade que pode ser comprada com algumas moedas; um favorito dos trabalhadores após um longo dia.",
  ["Rare Oil Painting"] = "Pintura a óleo rara",
