  ["Cocoa Milk Liqueur"] = "Licor de Leite de Cacau",
  ["Are you sure you want to perform a game repair? (Once confirmed, the game will exit and the repair process will execute upon reopening. This may take a long time; please wait patiently.)"] = "Tem certeza de que deseja realizar um reparo no jogo? (Depois de confirmado, o jogo será encerrado e o processo de reparo será executado na reabertura. Isso pode levar muito tempo; aguarde pacientemente.)",
  ["Hotfix Notice"] = "Aviso de hotfix",
  ["Pause download"] = "Pausar download",
  ["A large amount of resource loading is pending. Would you like to restart the game to download all resources? Click Cancel to continue playing while downloading, or click Confirm to restart the game. You will not be prompted again."] = "Uma grande quantidade de carregamento de recursos está pendente. Gostaria de reiniciar o jogo para baixar todos os recursos? Clique em Cancelar para continuar jogando durante o download ou clique em Confirmar para reiniciar o jogo. Você não será solicitado novamente.",
  ["Waiting to download"] = "Esperando para baixar",
  ["Network Exception"] = "Exceção de rede",
  ["{\"id\":1000,\"title\":\"Resource download complete\",\"body\":\"Download complete\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Download do recurso concluído\",\"body\":\"Download concluído\",\"pushMode\":0,\"delayInSeconds\":1}",
  ["{\"notificationTitle\": \"Resource download failed\",\"notificationContent\":\"Download failed\",\"showProgress\":false}"] = "{\"notificationTitle\": \"Falha no download do recurso\",\"notificationContent\":\"Falha no download\",\"showProgress\":false}",
